## 1. Generator System with Phase Alignment

### **a. GeneratorController.cs**

This script manages individual generators, ensuring they are phase-aligned before activation.

```csharp
using UnityEngine;

public class GeneratorController : MonoBehaviour
{
    public float frequency = 1f; // Hz
    public float phaseOffset = 0f; // Radians
    public bool isActive = false;

    private float currentPhase = 0f;
    private bool isAligned = false;

    // Reference to the global phase manager
    public PhaseManager phaseManager;

    void Start()
    {
        if (phaseManager == null)
        {
            Debug.LogError("PhaseManager reference not set on " + gameObject.name);
        }
    }

    void Update()
    {
        if (!isActive)
        {
            // Wait for phase alignment
            if (phaseManager != null && phaseManager.IsAligned)
            {
                isAligned = true;
                isActive = true;
                Debug.Log($"{gameObject.name} is now active and phase-aligned.");
            }
            return;
        }

        // Update phase based on time
        currentPhase += 2 * Mathf.PI * frequency * Time.deltaTime;
        currentPhase %= 2 * Mathf.PI;
    }

    public float GetCurrentPhase()
    {
        return currentPhase + phaseOffset;
    }
}
```

---

### **b. PhaseManager.cs**

This script manages the global phase alignment process.

```csharp
using UnityEngine;

public class PhaseManager : MonoBehaviour
{
    public float alignmentDuration = 2f; // seconds
    private float timer = 0f;
    public bool IsAligned { get; private set; } = false;

    void Start()
    {
        IsAligned = false;
        timer = 0f;
    }

    void Update()
    {
        if (!IsAligned)
        {
            timer += Time.deltaTime;
            if (timer >= alignmentDuration)
            {
                IsAligned = true;
                Debug.Log("Phase alignment complete. Generators can now activate.");
            }
        }
    }
}
```

