### **c. GeneratorGridManager.cs**

This script initializes and manages multiple generators on a grid.

```csharp
using UnityEngine;

public class GeneratorGridManager : MonoBehaviour
{
    public GameObject generatorPrefab;
    public int gridSizeX = 5;
    public int gridSizeY = 5;
    public float spacing = 2f;

    private PhaseManager phaseManager;

    void Start()
    {
        phaseManager = FindObjectOfType<PhaseManager>();
        for (int x = 0; x < gridSizeX; x++)
        {
            for (int y = 0; y < gridSizeY; y++)
            {
                Vector3 position = new Vector3(x * spacing, 0, y * spacing);
                GameObject gen = Instantiate(generatorPrefab, position, Quaternion.identity);
                var controller = gen.GetComponent<GeneratorController>();
                controller.phaseManager = phaseManager;
                // Optional: set individual phase offsets here
            }
        }
    }
}
