## 2. Sine Wave Shader (Oscilloscope Effect)

This shader visualizes a sine wave in a green oscilloscope style.

### **a. SineWaveOscilloscope.shader**

```shader
Shader "Custom/SineWaveOscilloscope"
{
    Properties
    {
        _MainTex ("Texture", 2D) = "white" {}
        _Amplitude ("Amplitude", Float) = 1.0
        _Frequency ("Frequency", Float) = 1.0
        _Speed ("Speed", Float) = 1.0
        _Color ("Color", Color) = (0,1,0,1)
    }
    SubShader
    {
        Tags { "RenderType"="Opaque" }
        LOD 100

        Pass
        {
            CGPROGRAM
            #pragma vertex vert
            #pragma fragment frag

            sampler2D _MainTex;
            float _Amplitude;
            float _Frequency;
            float _Speed;
            fixed4 _Color;

            struct appdata
            {
                float4 vertex : POSITION;
                float2 uv : TEXCOORD0;
            };

            struct v2f
            {
                float2 uv : TEXCOORD0;
                float4 vertex : SV_POSITION;
            };

            float time;

            v2f vert (appdata v)
            {
                v2f o;
                o.vertex = UnityObjectToClipPos(v.vertex);
                o.uv = v.uv;
                return o;
            }

            fixed4 frag (v2f i) : SV_Target
            {
                // Map UV.x to -π to π
                float x = (i.uv.x - 0.5) * 2.0 * 3.14159;
                // Calculate sine wave value
                float y = sin(_Frequency * x + _Speed * _Time.y);
                // Map y from -1..1 to 0..1
                float normalizedY = (y + 1.0) * 0.5;

                // Draw the wave in the middle of the texture
                float lineY = 0.5 + _Amplitude * y * 0.5;

                // Determine if current pixel is close to the wave line
                float lineThickness = 0.01; // Adjust for line thickness
                float dist = abs(i.uv.y - lineY);
                float alpha = smoothstep(lineThickness, 0.0, dist);

                // Green oscilloscope color
                fixed4 color = _Color;
                color.a = alpha;

                return color;
            }
            ENDCG
        }
    }
}
```

