<svg id="cradle" width="800" height="400"></svg>

<script>
  const svg = document.getElementById('cradle');

  // Configuration
  const NUM_SPHERES = 5;
  const SPHERE_RADIUS = 20;
  const SPACING = 50; // space between spheres
  const STRING_LENGTH = 150; // length of suspension strings
  const FRAME_WIDTH = 800;
  const FRAME_HEIGHT = 400;

  // Positions
  const cradleX = (FRAME_WIDTH - (NUM_SPHERES - 1) * SPACING) / 2;
  const cradleY = 50; // top position of the frame

  // Arrays to hold spheres and strings
  const spheres = [];
  const strings = [];

  // State variables for dragging
  let isDragging = false;
  let dragSphereIndex = 0; // index of the sphere being dragged
  let dragStart = { x: 0, y: 0 };
  let currentMouse = { x: 0, y: 0 };

  // Physics parameters
  const gravity = 0.98; // gravity acceleration
  const damping = 0.999; // damping factor for energy loss
  const timeStep = 0.016; // ~60 FPS

  // Initialize spheres and strings
  for (let i = 0; i < NUM_SPHERES; i++) {
    const x = cradleX + i * SPACING;
    const y = cradleY + STRING_LENGTH;

    // Create sphere
    const sphere = {
      index: i,
      x: x,
      y: y,
      vx: 0,
      vy: 0,
      radius: SPHERE_RADIUS,
      fixed: false, // only the first sphere is draggable
    };
    spheres.push(sphere);

    // Create string (line)
    const line = {
      x1: x,
      y1: cradleY,
      x2: x,
      y2: y,
    };
    strings.push(line);
  }

  // Draw the frame
  const frame = document.createElementNS("http://www.w3.org/2000/svg", "rect");
  frame.setAttribute("x", FRAME_WIDTH / 2 - 100);
  frame.setAttribute("y", cradleY - 20);
  frame.setAttribute("width", 200);
  frame.setAttribute("height", 20);
  frame.setAttribute("fill", "#888");
  svg.appendChild(frame);

  // Draw strings and spheres
