    // String
    const line = document.createElementNS("http://www.w3.org/2000/svg", "line");
    line.setAttribute("stroke", "#ccc");
    line.setAttribute("stroke-width", "2");
    svg.appendChild(line);
    strings[i].element = line;

    // Sphere
    const circle = document.createElementNS("http://www.w3.org/2000/svg", "circle");
    circle.setAttribute("cx", spheres[i].x);
    circle.setAttribute("cy", spheres[i].y);
    circle.setAttribute("r", SPHERE_RADIUS);
    circle.setAttribute("fill", "#bbb");
    circle.setAttribute("stroke", "#999");
    circle.setAttribute("stroke-width", "2");
    if (i === 0) {
      circle.classList.add("draggable");
    }
    svg.appendChild(circle);
    spheres[i].element = circle;
  }

  // Helper function to update the SVG elements
  function updateGraphics() {
    for (let i = 0; i < NUM_SPHERES; i++) {
      const s = spheres[i];
      // Update string
      const line = strings[i].element;
      line.setAttribute("x1", cradleX + i * SPACING);
      line.setAttribute("y1", cradleY);
      line.setAttribute("x2", s.x);
      line.setAttribute("y2", s.y);

      // Update sphere position
      s.element.setAttribute("cx", s.x);
      s.element.setAttribute("cy", s.y);
    }
  }

  // Physics simulation: constrain spheres to pendulum motion
  function simulate() {
    for (let i = 0; i < NUM_SPHERES; i++) {
      const s = spheres[i];

      if (i === 0 && isDragging) {
        // During dragging, position is controlled by mouse
        continue;
      }

      // Calculate the vector from the pivot point to the sphere
      const dx = s.x - (cradleX + i * SPACING);
      const dy = s.y - cradleY;
      const dist = Math.sqrt(dx * dx + dy * dy);
      const diff = dist - STRING_LENGTH;

      if (dist !== 0) {
        // Correct position to maintain string length
        const correction = (diff / dist) * 0.2; // correction factor
        s.x -= dx * correction;
        s.y -= dy * correction;
      }

      // Apply physics: simple pendulum physics
      // Calculate the angle
      const angle = Math.atan2(s.x - (cradleX + i * SPACING), s.y - cradleY);
      // For small angles, approximate motion
      // Here, for simplicity, we simulate swinging with basic physics

      // Update velocities
      s.vx *= damping;
      s.vy += gravity * timeStep;

      // Update positions
      s.x += s.vx;
      s.y += s.vy;

      // Constrain to the circle path (simulate pendulum swing)
      const dx2 = s.x - (cradleX + i * SPACING);
      const dy2 = s.y - cradleY;
      const dist2 = Math.sqrt(dx2 * dx2 + dy2 * dy2);
      if (dist2 !== 0) {
        const correction2 = (dist2 - STRING_LENGTH) / dist2;
        s.x -= dx2 * correction2;
        s.y -= dy2 * correction2;
      }
    }

    // Handle collisions (simple elastic collisions between spheres)
    for (let i = 0; i < NUM_SPHERES - 1; i++) {
      const s1 = spheres[i];
      const s2 = spheres[i + 1];

      const dx = s2.x - s1.x;
      const dy = s2.y - s1.y;
      const dist = Math.sqrt(dx * dx + dy * dy);
      if (dist < s1.radius + s2.radius && dist !== 0) {
        // Overlap detected, resolve collision
        const overlap = 0.5 * (dist - s1.radius - s2.radius);
        const nx = dx / dist;
        const ny = dy / dist;

        s1.x -= overlap * nx;
        s1.y -= overlap * ny;
        s2.x += overlap * nx;
        s2.y += overlap * ny;

        // Exchange velocities (elastic collision)
        const v1 = s1.vx * nx + s1.vy * ny;
        const v2 = s2.vx * nx + s2.vy * ny;

        const m1 = 1; // mass
        const m2 = 1;

        const v1After = v2;
        const v2After = v1;

        s1.vx += (v1After - v1) * nx;
        s1.vy += (v1After - v1) * ny;
        s2.vx += (v2After - v2) * nx;
        s2.vy += (v2After - v2) * ny;
      }
    }
  }

  // Animation loop
  function animate() {
    simulate();
    updateGraphics();
    requestAnimationFrame(animate);
  }

  // Event listeners for dragging
  svg.addEventListener('mousedown', (e) => {
    const rect = svg.getBoundingClientRect();
    const mouseX = e.clientX - rect.left;
    const mouseY = e.clientY - rect.top;

    // Check if clicked on the first sphere
    const s = spheres[0];
    const dx = mouseX - s.x;
    const dy = mouseY - s.y;
    if (dx * dx + dy * dy <= s.radius * s.radius) {
      isDragging = true;
      dragSphereIndex = 0;
      dragStart.x = mouseX;
      dragStart.y = mouseY;
      currentMouse.x = mouseX;
      currentMouse.y = mouseY;
    }
  });

  svg.addEventListener('mousemove', (e) => {
    if (isDragging) {
      const rect = svg.getBoundingClientRect();
      currentMouse.x = e.clientX - rect.left;
      currentMouse.y = e.clientY - rect.top;

      // Update sphere position directly
      const s = spheres[dragSphereIndex];
      s.x = currentMouse.x;
      s.y = currentMouse.y;

      // Calculate velocity based on movement
      s.vx = (s.x - dragStart.x) / timeStep;
      s.vy = (s.y - dragStart.y) / timeStep;

      dragStart.x = s.x;
      dragStart.y = s.y;
    }
  });

  svg.addEventListener('mouseup', () => {
    if (isDragging) {
      isDragging = false;
    }
  });

  // Optional: release sphere with physics
  document.addEventListener('mouseup', () => {
    if (isDragging) {
      isDragging = false;
    }
  });

  // Start animation
  animate();

</script>
