    align-items: center;
    height: 100vh;
    margin: 0;
  }
  canvas {
    border: 2px solid #fff;
    background: #000;
  }
</style>
</head>
<body>
<canvas id="tetris" width="240" height="400"></canvas>
<script>
const canvas = document.getElementById('tetris');
const ctx = canvas.getContext('2d');

const COLS = 10;
const ROWS = 20;
const BLOCK_SIZE = 20;

const shapes = [
  // I
  { shape: [[1,1,1,1]],
    color: 'cyan' },
  // J
  { shape: [[1,0,0],
            [1,1,1]],
    color: 'blue' },
  // L
  { shape: [[0,0,1],
            [1,1,1]],
    color: 'orange' },
  // O
  { shape: [[1,1],
            [1,1]],
    color: 'yellow' },
  // S
  { shape: [[0,1,1],
            [1,1,0]],
    color: 'green' },
  // T
  { shape: [[0,1,0],
            [1,1,1]],
    color: 'purple' },
  // Z
  { shape: [[1,1,0],
            [0,1,1]],
    color: 'red' }
];

let grid = [];
for (let r=0; r<ROWS; r++) {
  grid[r] = new Array(COLS).fill(0);
}

let currentPiece = null;
let currentX = 0;
let currentY = 0;
let gameOver = false;
let score = 0;

// Helper functions
function createPiece() {
  const index = Math.floor(Math.random() * shapes.length);
  const shape = shapes[index].shape;
  const color = shapes[index].color;
  return { shape, color };
}

function newPiece() {
  currentPiece = createPiece();
  currentX = Math.floor(COLS/2) - Math.ceil(currentPiece.shape[0].length/2);
  currentY = 0;
  if (collision(currentX, currentY, currentPiece.shape)) {
    gameOver = true;
  }
}

function collision(x, y, shape) {
  for (let r=0; r<shape.length; r++) {
    for (let c=0; c<shape[r].length; c++) {
      if (shape[r][c]) {
        let newX = x + c;
        let newY = y + r;
        if (newX < 0 || newX >= COLS || newY >= ROWS || (newY >=0 && grid[newY][newX])) {
          return true;
        }
      }
    }
  }
  return false;
}

function merge() {
  const shape = currentPiece.shape;
  for (let r=0; r<shape.length; r++) {
    for (let c=0; c<shape[r].length; c++) {
      if (shape[r][c]) {
        let x = currentX + c;
        let y = currentY + r;
        if (y >= 0) {
          grid[y][x] = currentPiece.color;
        }
      }
    }
  }
}

function clearLines() {
  let linesCleared = 0;
  for (let y=ROWS-1; y>=0; y--) {
    if (grid[y].every(cell => cell)) {
      grid.splice(y,1);
      grid.unshift(new Array(COLS).fill(0));
      linesCleared++;
      y++;
    }
  }
  score += linesCleared * 100;
}

function rotate(shape) {
  const rows = shape.length;
  const cols = shape[0].length;
  let newShape = [];
  for (let c=0; c<cols; c++) {
    newShape[c] = [];
    for (let r=rows-1; r>=0; r--) {
      newShape[c][rows - 1 - r] = shape[r][c];
    }
  }
  return newShape;
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  // Draw grid
  for (let r=0; r<ROWS; r++) {
    for (let c=0; c<COLS; c++) {
      if (grid[r][c]) {
        ctx.fillStyle = grid[r][c];
        ctx.fillRect(c*BLOCK_SIZE, r*BLOCK_SIZE, BLOCK_SIZE, BLOCK_SIZE);
        ctx.strokeStyle = '#222';
        ctx.strokeRect(c*BLOCK_SIZE, r*BLOCK_SIZE, BLOCK_SIZE, BLOCK_SIZE);
      } else {
        ctx.fillStyle = '#000';
        ctx.fillRect(c*BLOCK_SIZE, r*BLOCK_SIZE, BLOCK_SIZE, BLOCK_SIZE);
        ctx.strokeStyle = '#222';
        ctx.strokeRect(c*BLOCK_SIZE, r*BLOCK_SIZE, BLOCK_SIZE, BLOCK_SIZE);
      }
    }
  }
  // Draw current piece
  if (currentPiece) {
    ctx.fillStyle = currentPiece.color;
    for (let r=0; r<currentPiece.shape.length; r++) {
      for (let c=0; c<currentPiece.shape[r].length; c++) {
        if (currentPiece.shape[r][c]) {
          let x = (currentX + c) * BLOCK_SIZE;
          let y = (currentY + r) * BLOCK_SIZE;
          ctx.fillRect(x, y, BLOCK_SIZE, BLOCK_SIZE);
          ctx.strokeStyle = '#222';
          ctx.strokeRect(x, y, BLOCK_SIZE, BLOCK_SIZE);
        }
      }
    }
  }
  // Draw score
  ctx.fillStyle = 'white';
  ctx.font = '16px Arial';
  ctx.fillText('Score: ' + score, 10, 20);
}

let dropCounter = 0;
let dropInterval = 500; // milliseconds
let lastTime = 0;

function update(time = 0) {
  if (gameOver) {
    ctx.fillStyle = 'white';
    ctx.font = '24px Arial';
    ctx.fillText('Game Over', canvas.width/2 - 60, canvas.height/2);
    return;
  }
  const deltaTime = time - lastTime;
  lastTime = time;
  dropCounter += deltaTime;
  if (dropCounter > dropInterval) {
    moveDown();
    dropCounter = 0;
  }
  draw();
  requestAnimationFrame(update);
}

function moveDown() {
  if (!collision(currentX, currentY + 1, currentPiece.shape)) {
    currentY++;
  } else {
    merge();
    clearLines();
    newPiece();
  }
}

function moveLeft() {
  if (!collision(currentX - 1, currentY, currentPiece.shape)) {
    currentX--;
  }
}

function moveRight() {
  if (!collision(currentX + 1, currentY, currentPiece.shape)) {
    currentX++;
  }
}

function rotatePiece() {
  const newShape = rotate(currentPiece.shape);
  if (!collision(currentX, currentY, newShape)) {
    currentPiece.shape = newShape;
  }
}

// Event listeners
document.addEventListener('keydown', e => {
  if (gameOver) return;
  if (e.key === 'ArrowLeft') {
    moveLeft();
  } else if (e.key === 'ArrowRight') {
    moveRight();
  } else if (e.key === 'ArrowDown') {
    moveDown();
  } else if (e.key === 'ArrowUp') {
    rotatePiece();
  } else if (e.key === ' ') {
    // Hard drop
    while (!collision(currentX, currentY + 1, currentPiece.shape)) {
      currentY++;
    }
    moveDown();
  }
});

// Start game
newPiece();
requestAnimationFrame(update);
</script>
</body>
</html>
```

### How it works:
- The game uses a `<canvas>` element to render the grid and pieces.
- Shapes are randomly selected from standard Tetris pieces.
- The game automatically drops pieces every 500ms.
- Use arrow keys to move left/right/down, up arrow to rotate, and spacebar for a hard drop.
- When a line is completed, it clears and increases the score.
- The game ends when new pieces cannot spawn.

