let currentRotation = 0;
let currentX = 0;
let currentY = 0;
let gameOver = false;

// Helper functions
function newShape() {
  const shapeIndex = Math.floor(Math.random() * shapes.length);
  const shape = shapes[shapeIndex];
  currentShape = shape;
  currentRotation = 0;
  currentX = Math.floor(COLS/2) - Math.ceil(shape.rotations[currentRotation][0].length/2);
  currentY = 0;
  if (collision(currentX, currentY, currentRotation)) {
    gameOver = true;
  }
}

function collision(x, y, rotationIndex) {
  const shapeMatrix = currentShape.rotations[rotationIndex];
  for (let r=0; r<shapeMatrix.length; r++) {
    for (let c=0; c<shapeMatrix[r].length; c++) {
      if (shapeMatrix[r][c]) {
        const newX = x + c;
        const newY = y + r;
        if (
          newX < 0 || newX >= COLS ||
          newY >= ROWS ||
          (newY >=0 && board[newY][newX])
        ) {
          return true;
        }
      }
    }
  }
  return false;
}

function merge() {
  const shapeMatrix = currentShape.rotations[currentRotation];
  for (let r=0; r<shapeMatrix.length; r++) {
    for (let c=0; c<shapeMatrix[r].length; c++) {
      if (shapeMatrix[r][c]) {
        const x = currentX + c;
        const y = currentY + r;
        if (y >= 0) {
          board[y][x] = currentShape.color;
        }
      }
    }
  }
}

function clearLines() {
  let linesCleared = 0;
  for (let y=ROWS-1; y>=0; y--) {
    if (board[y].every(cell => cell)) {
      board.splice(y,1);
      board.unshift(new Array(COLS).fill(0));
      linesCleared++;
      y++;
    }
  }
  if (linesCleared > 0) {
    score += linesCleared * 100;
    scoreElement.textContent = 'Score: ' + score;
  }
}

function drawCell(x, y, color) {
  ctx.fillStyle = color;
  ctx.fillRect(x*BLOCK_SIZE, y*BLOCK_SIZE, BLOCK_SIZE, BLOCK_SIZE);
  ctx.strokeStyle = '#222';
  ctx.strokeRect(x*BLOCK_SIZE, y*BLOCK_SIZE, BLOCK_SIZE, BLOCK_SIZE);
}

function drawBoard() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  for (let y=0; y<ROWS; y++) {
    for (let x=0; x<COLS; x++) {
      if (board[y][x]) {
        drawCell(x, y, board[y][x]);
      }
    }
  }
  // Draw current shape
  const shapeMatrix = currentShape.rotations[currentRotation];
  for (let r=0; r<shapeMatrix.length; r++) {
    for (let c=0; c<shapeMatrix[r].length; c++) {
      if (shapeMatrix[r][c]) {
        drawCell(currentX + c, currentY + r, currentShape.color);
      }
    }
  }
}

function gameLoop() {
  if (gameOver) {
    alert('Game Over! Your score: ' + score);
    return;
  }
  if (!moveDown()) {
    merge();
    clearLines();
    newShape();
  }
  drawBoard();
  setTimeout(gameLoop, 500);
}

function moveDown() {
  if (!collision(currentX, currentY + 1, currentRotation)) {
    currentY++;
    return true;
  }
  return false;
}

function moveLeft() {
  if (!collision(currentX -1, currentY, currentRotation)) {
    currentX--;
  }
}

function moveRight() {
  if (!collision(currentX +1, currentY, currentRotation)) {
    currentX++;
  }
}

function rotate() {
  const nextRotation = (currentRotation +1) % currentShape.rotations.length;
  if (!collision(currentX, currentY, nextRotation)) {
    currentRotation = nextRotation;
  }
}

// Event listeners
document.addEventListener('keydown', (e) => {
  if (gameOver) return;
  switch(e.key) {
    case 'ArrowLeft':
      moveLeft();
      break;
    case 'ArrowRight':
      moveRight();
      break;
    case 'ArrowDown':
      moveDown();
      break;
    case 'ArrowUp':
      rotate();
      break;
    case ' ':
      // Hard drop
      while (moveDown()) {}
      break;
  }
  drawBoard();
});

// Start game
newShape();
drawBoard();
gameLoop();
</script>
</body>
</html>
```

### How it works:
- The game uses a `<canvas>` element to render the Tetris grid.
- Shapes are defined with their rotations and colors.
- The game loop moves the current piece down every 500ms.
- Arrow keys move and rotate the pieces; space performs a hard drop.
- When a piece lands, it merges into the board, and completed lines are cleared.
- The game ends when new pieces cannot spawn.

