<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8" />
<title>Flappy Bird Clone with Three.js</title>
<style>body { margin: 0; overflow: hidden; }</style>
</head>
<body>
<script src="https://cdn.jsdelivr.net/npm/three@0.152.0/build/three.min.js"></script>
<script>
let scene, camera, renderer;
let bird, pipes = [], pipeSpacing = 15, pipeWidth = 3, pipeGap = 8;
let gravity = 0.002, lift = 0.05, velocityY = 0;
let clock = new THREE.Clock();
let cameraOffsetX = 0;
let gameOver = false;

init();
animate();

function init() {
scene = new THREE.Scene();
camera = new THREE.PerspectiveCamera(75, window.innerWidth/window.innerHeight, 0.1, 1000);
renderer = new THREE.WebGLRenderer({antialias:true});
renderer.setSize(window.innerWidth, window.innerHeight);
document.body.appendChild(renderer.domElement);

const birdGeometry = new THREE.BoxGeometry(1, 1, 1);
const birdMaterial = new THREE.MeshBasicMaterial({color: 0xffff00});
bird = new THREE.Mesh(birdGeometry, birdMaterial);
bird.position.x = 0;
bird.position.y = 0;
scene.add(bird);

for(let i=0; i<10; i++) {
    createPipe(i * pipeSpacing + 20);
}

window.addEventListener('resize', () => {
    camera.aspect = window.innerWidth/window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
});

window.addEventListener('mousedown', () => {
    if(!gameOver) velocityY += lift;
});

function createPipe(x) {
    const topHeight = Math.random() * 10 + 10;
    const bottomHeight = 20 - topHeight - pipeGap;
    const pipeMaterial = new THREE.MeshBasicMaterial({color: 0x00ff00});
    const topGeometry = new THREE.BoxGeometry(pipeWidth, topHeight, 1);
    const bottomGeometry = new THREE.BoxGeometry(pipeWidth, bottomHeight, 1);
    const topPipe = new THREE.Mesh(topGeometry, pipeMaterial);
    topPipe.position.x = x;
    topPipe.position.y = 10 + topHeight/2;
    const bottomPipe = new THREE.Mesh(bottomGeometry, pipeMaterial);
    bottomPipe.position.x = x;
    bottomPipe.position.y = -10 - bottomHeight/2;
    scene.add(topPipe);
    scene.add(bottomPipe);
    pipes.push({top: topPipe, bottom: bottomPipe, x: x, passed: false});
}

function animate() {
    requestAnimationFrame(animate);
    if(gameOver) {
        renderer.render(scene, camera);
        return;
    }
    const delta = clock.getDelta();

    velocityY -= gravity;
