```cpp
#include <format>
#include <string>

// Define the Data struct
struct Data {
    int v;

    void method() {
        // Implementation of method (can be empty or as needed)
    }
};

// Specialize std::formatter for Data
template <>
struct std::formatter<Data> {
    // Parse function (no custom formatting options)
    constexpr auto parse(std::format_parse_context& ctx) {
        // No options, so just return the parse iterator
        return ctx.begin();
    }

    // Format function
    auto format(const Data& data, std::format_context& ctx) {
        // Format the Data object as desired
        // For example, just output the value of v
        return std::format_to(ctx.out(), "Data{{v={}}}", data.v);
    }
};
```

**Usage example:**

```cpp
#include <iostream>
