<script>
  // Initialize Canvas and Scene
  const canvas = document.getElementById('launchCanvas');
  const ctx = canvas.getContext('2d');
  let width = window.innerWidth;
  let height = window.innerHeight;
  canvas.width = width;
  canvas.height = height;

  window.addEventListener('resize', () => {
    width = window.innerWidth;
    height = window.innerHeight;
    canvas.width = width;
    canvas.height = height;
  });

  // Rocket parameters
  const rocket = {
    x: width / 2,
    y: height - 50,
    width: 20,
    height: 60,
    color: '#ff0000',
    velocityY: 0,
    isLaunching: false,
    hasLaunched: false,
    ascentSpeed: 0.5,
    stage: 1 // 1: on ground, 2: ascending, 3: in space
  };

  // Atmosphere and space parameters
  const atmosphereHeight = height * 0.4; // height of atmosphere
  const spaceThreshold = height - 50; // y position to consider entering space

  // Particles for smoke and stars
  const particles = [];

  // Function to create smoke particles
function createSmoke(x, y) {
  particles.push({
    x: x + (Math.random() - 0.5) * 10,
    y: y + Math.random() * 10,
    radius: Math.random() * 3 + 2,
    alpha: 1,
    vx: (Math.random() - 0.5) * 0.5,
    vy: -Math.random() * 0.5 - 0.2,
    color: 'rgba(200,200,200,'
  });
}

// Function to create stars
function createStar() {
  return {
    x: Math.random() * width,
    y: Math.random() * height * 0.5,
    radius: Math.random() * 1.5,
    alpha: Math.random(),
  };
}

// Generate initial stars
const stars = [];
for (let i = 0; i < 100; i++) {
  stars.push(createStar());
}

// Animation loop
function animate() {
  ctx.clearRect(0, 0, width, height);

  // Draw background gradient (sky)
  const gradient = ctx.createLinearGradient(0, height, 0, 0);
  gradient.addColorStop(0, '#0d1b2a');
  gradient.addColorStop(0.5, '#1b263b');
  gradient.addColorStop(0.8, '#415a77');
  gradient.addColorStop(1, '#778da9');
  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, width, height);

  // Draw stars if in space
  if (rocket.stage === 3) {
    ctx.fillStyle = 'white';
    stars.forEach(star => {
      ctx.globalAlpha = star.alpha;
      ctx.beginPath();
      ctx.arc(star.x, star.y, star.radius, 0, Math.PI * 2);
      ctx.fill();
    });
    ctx.globalAlpha = 1;
  }

  // Draw Earth at bottom
  ctx.fillStyle = '#3b0b0b';
  ctx.beginPath();
  ctx.arc(width/2, height + 100, 150, Math.PI, 0, false);
  ctx.fill();

  // Draw atmosphere (optional visual)
  if (rocket.y < height - atmosphereHeight) {
    ctx.fillStyle = 'rgba(255,255,255,0.1)';
    ctx.fillRect(0, height - atmosphereHeight, width, atmosphereHeight);
  }

  // Draw rocket
  ctx.save();
  ctx.translate(rocket.x, rocket.y);
  ctx.fillStyle = rocket.color;
  ctx.beginPath();
  ctx.moveTo(0, -rocket.height / 2);
  ctx.lineTo(-rocket.width / 2, rocket.height / 2);
  ctx.lineTo(rocket.width / 2, rocket.height / 2);
  ctx.closePath();
  ctx.fill();

  // Rocket flame when launching
  if (rocket.isLaunching && rocket.y > height - atmosphereHeight) {
    ctx.beginPath();
    ctx.moveTo(0, rocket.height / 2);
    ctx.lineTo(-5, rocket.height / 2 + 15);
    ctx.lineTo(5, rocket.height / 2 + 15);
    ctx.closePath();
    ctx.fillStyle = 'orange';
    ctx.fill();
  }
  ctx.restore();

  // Update rocket position
  if (rocket.isLaunching) {
    // Apply acceleration
    rocket.velocityY -= rocket.ascentSpeed;
    rocket.y += rocket.velocityY;

    // Create smoke particles
    createSmoke(rocket.x, rocket.y + rocket.height / 2);

    // Check if rocket has reached space
    if (rocket.y < spaceThreshold) {
      rocket.stage = 3; // in space
    }
  } else {
    // Rocket on ground, wait for launch
  }

  // Update particles
  for (let i = particles.length - 1; i >= 0; i--) {
    const p = particles[i];
    p.x += p.vx;
    p.y += p.vy;
    p.alpha -= 0.02;
    if (p.alpha <= 0) {
      particles.splice(i, 1);
    } else {
      ctx.globalAlpha = p.alpha;
      ctx.fillStyle = p.color + p.alpha + ')';
      ctx.beginPath();
      ctx.arc(p.x, p.y, p.radius, 0, Math.PI * 2);
      ctx.fill();
    }
  }
  ctx.globalAlpha = 1;

  // Draw stars in space
  if (rocket.stage === 3) {
    stars.forEach(star => {
      star.alpha += (Math.random() - 0.5) * 0.02;
      star.alpha = Math.max(0, Math.min(1, star.alpha));
    });
  }

  requestAnimationFrame(animate);
}

// Launch on click
canvas.addEventListener('click', () => {
  if (!rocket.isLaunching && rocket.stage !== 3) {
    rocket.isLaunching = true;
    rocket.velocityY = 0;
  }
});

// Optional: add keyboard control for launch
window.addEventListener('keydown', (e) => {
  if (e.code === 'Space') {
    if (!rocket.isLaunching && rocket.stage !== 3) {
      rocket.isLaunching = true;
      rocket.velocityY = 0;
    }
  }
});

// Start animation
animate();
</script>
</body>
</html>
