let bottomPipe = new THREE.Mesh(bottomPipeGeo, pipeMat);
bottomPipe.position.set(x, gapY - pipeGap/2 - 1.5, 0);
pipes.push({top: topPipe, bottom: bottomPipe, x: x});
scene.add(topPipe, bottomPipe);
}

