  if (isSpinning) return;
  isSpinning = true;
  resultDiv.textContent = '';

  // Disable button during spin
  spinBtn.disabled = true;

  // Randomly determine the final stop position
  const targetSegmentIndex = Math.floor(Math.random() * numSegments);
  const arcSize = (2 * Math.PI) / numSegments;

  // Calculate the angle to land on the target segment (pointer points at 0 radians)
  const targetAngle = (2 * Math.PI * 3) + // 3 full rotations for effect
                      (Math.PI * 2 - (targetSegmentIndex * arcSize + arcSize / 2));

  // Add some randomness within the segment
  const randomOffset = (Math.random() - 0.5) * arcSize * 0.8; // +/-40% of segment
  const finalAngle = targetAngle + randomOffset;

  const duration = 4000; // spin duration in ms
  const startTime = performance.now();
  const initialAngle = currentAngle;
  const totalRotation = finalAngle - initialAngle;

  function animate(currentTime) {
    const elapsed = currentTime - startTime;
    const progress = Math.min(elapsed / duration, 1);
    // Ease out cubic
    const easeProgress = 1 - Math.pow(1 - progress, 3);
    currentAngle = initialAngle + totalRotation * easeProgress;
    drawWheel(currentAngle);
    if (progress < 1) {
      spinAnimationId = requestAnimationFrame(animate);
    } else {
      // Spin finished
      isSpinning = false;
      // Determine the winning segment
      const normalizedAngle = (currentAngle + Math.PI * 2) % (2 * Math.PI);
      const index = Math.floor((2 * Math.PI - normalizedAngle + arcSize / 2) % (2 * Math.PI) / arcSize);
      const winningSegment = segments[index];
      resultDiv.textContent = `Result: ${winningSegment.label}`;
      spinBtn.disabled = false;
    }
  }

  spinAnimationId = requestAnimationFrame(animate);
}

// Initial draw
drawWheel(currentAngle);

// Event listener
document.getElementById('spinBtn').addEventListener('click', spin);
</script>

