        url_league = API_BASE_URL + "/league/" + LEAGUE_ID
        url_team = API_BASE_URL + "/team/" + TEAM_ID
        // Add more URLs as needed

        // Fetch data concurrently
        league_data_task = fetch_data(session, url_league, headers)
        team_data_task = fetch_data(session, url_team, headers)
        // Add more tasks as needed

        // Wait for all data to be fetched
        league_data, team_data = await asyncio.gather(league_data_task, team_data_task)

        // Process and extract relevant data
        processed_data = process_data(league_data, team_data)

        // Export to CSV
        write_to_csv(processed_data, OUTPUT_CSV_FILE)

