### Example Go Program:

```go
package main

import (
	"fmt"
	"math"
	"sort"
)

// Option represents an individual option contract
type Option struct {
	Strike       float64
	BidPrice     float64
	AskPrice     float64
	ImpliedVol   float64 // implied volatility as decimal (e.g., 0.2 for 20%)
	TimeToExpiration float64 // in years
}

// Helper function to compute the midpoint price
func midpoint(bid, ask float64) float64 {
	return (bid + ask) / 2.0
}

// Function to select options around the at-the-money strike
func selectOptions(options []Option, atmStrike float64, rangePercent float64) []Option {
	var selected []Option
	lowerBound := atmStrike * (1 - rangePercent)
	upperBound := atmStrike * (1 + rangePercent)
	for _, opt := range options {
		if opt.Strike >= lowerBound && opt.Strike <= upperBound {
			selected = append(selected, opt)
		}
	}
	return selected
}

// Function to compute the variance for a set of options
func computeVariance(options []Option, F float64, T float64) float64 {
	var sum float64
	var k0 float64
	var deltaK float64

	// Sort options by strike
	sort.Slice(options, func(i, j int) bool {
		return options[i].Strike < options[j].Strike
	})

	// Find the at-the-money strike (closest to F)
	atmIndex := 0
	minDiff := math.Abs(options[0].Strike - F)
	for i, opt := range options {
		if diff := math.Abs(opt.Strike - F); diff < minDiff {
			minDiff = diff
			atmIndex = i
		}
	}
	k0 = options[atmIndex].Strike

	// Calculate the sum over options
	for i, opt := range options {
		// Use midpoint price
		price := midpoint(opt.BidPrice, opt.AskPrice)
		// Implied volatility
		iv := opt.ImpliedVol
		// Strike
		K := opt.Strike
		// Time to expiration
		T := opt.TimeToExpiration

		// Calculate deltaK
		if i == 0 {
			deltaK = options[i+1].Strike - K
		} else if i == len(options)-1 {
			deltaK = K - options[i-1].Strike
		} else {
			deltaK = (options[i+1].Strike - options[i-1].Strike) / 2
		}

		// Contribution to variance
		term := (deltaK / (K * K)) * math.Exp(T*0) * price // assuming risk-free rate = 0 for simplicity
		sum += term
	}

	// Variance calculation
	variance := (2 / T) * sum - (1 / T) * ((F / k0 - 1) * (F / k0 - 1))
	return variance
}

// Main function to compute the VIX-like index
func computeVIX(options []Option, spotPrice float64, T float64) float64 {
	// Select options around ATM
	selectedOptions := selectOptions(options, spotPrice, 0.2) // 20% range

	if len(selectedOptions) == 0 {
		fmt.Println("No options selected. Check your data.")
		return 0
	}

	// Compute variance
