    font-size: 30px;
    display: none;
  }
  #restart {
    margin-top: 10px;
    padding: 8px 16px;
    font-size: 16px;
    cursor: pointer;
  }
</style>
</head>
<body>
<canvas id="gameCanvas" width="800" height="400"></canvas>
<div id="score">Score: 0</div>
<div id="gameOver">
  Game Over!
  <br />
  <button id="restart">Restart</button>
</div>
<script>
  const canvas = document.getElementById('gameCanvas');
  const ctx = canvas.getContext('2d');
  const scoreDiv = document.getElementById('score');
  const gameOverDiv = document.getElementById('gameOver');
  const restartBtn = document.getElementById('restart');

  const WIDTH = canvas.width;
  const HEIGHT = canvas.height;

  // Player properties
  const player = {
    x: 50,
    y: HEIGHT - 50,
    width: 30,
    height: 30,
    color: '#00ff00',
    velocityY: 0,
    gravity: 0.5,
    jumpStrength: -10,
    isJumping: false
  };

  // Spikes array
  const spikes = [];
  let spawnTimer = 0;
  const spawnInterval = 90; // frames
  let gameSpeed = 6;

  let score = 0;
  let gameOver = false;

  // Input handling
  document.addEventListener('keydown', (e) => {
    if (e.code === 'Space' || e.code === 'KeyW' || e.code === 'ArrowUp') {
      jump();
    }
  });
  document.addEventListener('touchstart', () => {
    jump();
  });

  function jump() {
    if (!player.isJumping) {
      player.velocityY = player.jumpStrength;
      player.isJumping = true;
    }
  }

  function reset() {
    // Reset game state
    player.x = 50;
    player.y = HEIGHT - 50;
    player.velocityY = 0;
    player.isJumping = false;
    spikes.length = 0;
    score = 0;
    gameSpeed = 6;
    gameOver = false;
    document.getElementById('gameOver').style.display = 'none';
    updateScore();
    loop();
  }

  function updateScore() {
    scoreDiv.textContent = 'Score: ' + score;
  }

  function spawnSpike() {
    const spikeWidth = 20 + Math.random() * 10;
    const spikeHeight = 20 + Math.random() * 20;
    const spikeX = WIDTH + Math.random() * 100;
    const spikeY = HEIGHT - spikeHeight;
    spikes.push({ x: spikeX, y: spikeY, width: spikeWidth, height: spikeHeight });
  }

  function update() {
    if (gameOver) return;

    // Update player
    player.velocityY += player.gravity;
    player.y += player.velocityY;

    // Prevent falling below ground
    if (player.y + player.height >= HEIGHT) {
      player.y = HEIGHT - player.height;
      player.velocityY = 0;
      player.isJumping = false;
    }

    // Spawn spikes
    spawnTimer++;
    if (spawnTimer >= spawnInterval) {
      spawnSpike();
      spawnTimer = 0;
    }

    // Move spikes
    for (let i = spikes.length - 1; i >= 0; i--) {
      spikes[i].x -= gameSpeed;
      // Remove off-screen spikes
      if (spikes[i].x + spikes[i].width < 0) {
        spikes.splice(i, 1);
        score++;
        updateScore();
        // Increase difficulty
        if (score % 10 === 0) {
          gameSpeed += 0.5;
        }
      }
    }

    // Check collisions
    for (let spike of spikes) {
      if (
        player.x < spike.x + spike.width &&
        player.x + player.width > spike.x &&
        player.y < spike.y + spike.height &&
        player.y + player.height > spike.y
      ) {
        endGame();
        break;
      }
    }
  }

  function draw() {
    ctx.clearRect(0, 0, WIDTH, HEIGHT);

    // Draw ground
    ctx.fillStyle = '#555';
    ctx.fillRect(0, HEIGHT - 10, WIDTH, 10);

    // Draw player
    ctx.fillStyle = player.color;
    ctx.fillRect(player.x, player.y, player.width, player.height);

    // Draw spikes
    ctx.fillStyle = '#ff0000';
    for (let spike of spikes) {
      ctx.beginPath();
      ctx.moveTo(spike.x, HEIGHT);
      ctx.lineTo(spike.x + spike.width / 2, spike.y);
      ctx.lineTo(spike.x + spike.width, HEIGHT);
      ctx.closePath();
      ctx.fill();
    }
  }

  function loop() {
    update();
    draw();
    if (!gameOver) {
      requestAnimationFrame(loop);
    }
  }

  function endGame() {
    gameOver = true;
    document.getElementById('gameOver').style.display = 'block';
  }

  restartBtn.addEventListener('click', reset);

  // Start the game
  reset();
</script>
</body>
</html>
```

### How it works:
- The player is a green square that can jump when pressing space, W, or the up arrow, or by touching the screen.
- Spikes are generated periodically and move from right to left.
- The player must jump over the spikes.
- The game ends when the player collides with a spike.
- The score increases for each spike successfully avoided.
- The game speed increases gradually to make it more challenging.

