        return 0

def wavelength_to_blue(wavelength):
    if 380 <= wavelength <= 495:
        return int(255 * (495 - wavelength) / (495 - 380))
    elif 495 < wavelength <= 570:
        return 0
    elif 380 <= wavelength < 495:
        return 255
