Certainly! Here's a PowerShell script that searches recursively from a specified directory (or current directory if none specified) for Git repositories (directories containing a `.git` folder) and then determines the date of their initial commit.

```powershell
param(
    [string]$StartPath = (Get-Location)
)

# Function to find all Git repositories recursively
function Get-GitRepositories {
    param([string]$Path)

    Get-ChildItem -Path $Path -Directory -Recurse -Force -ErrorAction SilentlyContinue | Where-Object {
        Test-Path -Path (Join-Path $_.FullName ".git")
    } | Select-Object -Property FullName
}

# Function to get the initial commit date of a Git repository
function Get-InitialCommitDate {
    param([string]$RepoPath)

    # Use git command to get the first commit date
    $gitDir = Join-Path $RepoPath ".git"
    if (-Not (Test-Path $gitDir)) {
        return "Not a Git repository"
    }

    # Run git log to find the earliest commit
    $initialCommit = git -C $RepoPath log --reverse --format="%H %ct" | Select-Object -First 1

    if ($initialCommit) {
        # Parse commit hash and timestamp
        $parts = $initialCommit -split ' '
        $commitHash = $parts[0]
        $timestamp = [int]$parts[1]
        $date = Get-Date -UnixTimeSeconds $timestamp
        return $date
    } else {
        return "No commits found"
    }
}

# Main script
$repositories = Get-GitRepositories -Path $StartPath

if ($repositories) {
    foreach ($repo in $repositories) {
        Write-Output "Repository: $repo"
        $initialDate = Get-InitialCommitDate -RepoPath $repo
        Write-Output "Initial Commit Date: $initialDate"
        Write-Output "------------------------------"
    }
} else {
    Write-Output "No Git repositories found under $StartPath"
}
```

### How to use:
1. Save this script as `Find-GitInitialCommitDate.ps1`.
2. Open PowerShell.
3. Run the script, optionally specifying a starting directory:
   ```powershell
   .\Find-GitInitialCommitDate.ps1 -StartPath "C:\Path\To\Search"
   ```
   Or just run it without parameters to search from the current directory:
   ```powershell
   .\Find-GitInitialCommitDate.ps1
   ```

### Notes:
- This script requires Git to be installed and accessible via the command line.
- It searches recursively for directories containing a `.git` folder.
- For each repository found, it retrieves the date of the initial commit.

