const posts = []; // In-memory posts store
let postIdCounter = 1;

// Secret key for JWT
const SECRET_KEY = 'your_secret_key';

// Register endpoint
app.post('/register', async (req, res) => {
  const { username, password } = req.body;
  const hashedPassword = await bcrypt.hash(password, 10);
  users.push({ username, password: hashedPassword });
  res.json({ message: 'User registered' });
});

// Login endpoint
app.post('/login', async (req, res) => {
  const { username, password } = req.body;
  const user = users.find(u => u.username === username);
  if (!user) return res.status(400).json({ message: 'Invalid credentials' });
  const match = await bcrypt.compare(password, user.password);
  if (!match) return res.status(400).json({ message: 'Invalid credentials' });
  const token = jwt.sign({ username }, SECRET_KEY);
  res.json({ token });
});

// Middleware to authenticate
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];
  if (!token) return res.sendStatus(401);
  jwt.verify(token, SECRET_KEY, (err, user) => {
    if (err) return res.sendStatus(403);
    req.user = user;
    next();
  });
}

// Create post
app.post('/posts', authenticateToken, (req, res) => {
  const { title, content } = req.body;
  const newPost = {
    id: postIdCounter++,
    author: req.user.username,
    title,
    content,
    ratings: [],
  };
  posts.push(newPost);
  res.json(newPost);
});

// Rate a post
app.post('/posts/:id/rate', authenticateToken, (req, res) => {
  const { id } = req.params;
  const { rating } = req.body; // rating from 1 to 5
  const post = posts.find(p => p.id == id);
  if (!post) return res.status(404).json({ message: 'Post not found' });
  post.ratings.push({ username: req.user.username, rating });
  res.json({ message: 'Rating added' });
});

// Get posts with average rating
app.get('/posts', (req, res) => {
  const result = posts.map(post => {
    const total = post.ratings.reduce((sum, r) => sum + r.rating, 0);
    const avgRating = post.ratings.length ? (total / post.ratings.length) : 0;
    return { ...post, averageRating: avgRating.toFixed(2) };
  });
  res.json(result);
});

app.listen(3000, () => {
