<h1>Vocabulary Practice App</h1>

<div class="section" id="database-section">
  <h2>Vocabulary Database</h2>
  <button onclick="loadSampleData()">Load Sample Data</button>
  <button onclick="saveDatabase()">Save Database</button>
  <button onclick="clearDatabase()">Clear Database</button>
  <h3>Current Vocabulary List</h3>
  <table id="vocab-table">
    <thead>
      <tr>
        <th>Word</th>
        <th>Definition</th>
        <th>Mastered</th>
        <th>Actions</th>
      </tr>
    </thead>
    <tbody></tbody>
  </table>
  <h3>Add New Word</h3>
  <input type="text" id="new-word" placeholder="Word" />
  <input type="text" id="new-definition" placeholder="Definition" />
  <button onclick="addVocabulary()">Add</button>
</div>

<div class="section" id="test-section">
  <h2>Vocabulary Test</h2>
  <label>
    <input type="checkbox" id="exclude-mastered" checked />
    Exclude mastered vocabulary
  </label>
  <br/><br/>
  <button onclick="startTest()">Start Test</button>
  <div id="test-area" class="hidden">
    <p id="question"></p>
    <input type="text" id="answer" placeholder="Your answer" />
    <button onclick="submitAnswer()">Submit</button>
    <p id="feedback"></p>
    <p>Score: <span id="score">0</span></p>
    <button onclick="endTest()">End Test</button>
  </div>
</div>

<script>
  // Initialize database from localStorage or create empty
  let vocabularyDB = JSON.parse(localStorage.getItem('vocabularyDB')) || [];

  // Variables for testing
  let testWords = [];
  let currentWord = null;
  let score = 0;
  let totalQuestions = 0;

  // Load sample data
  function loadSampleData() {
    vocabularyDB = [
      { word: 'Apple', definition: 'A fruit', mastered: false },
      { word: 'Banana', definition: 'A yellow fruit', mastered: false },
      { word: 'Cat', definition: 'A small domesticated carnivorous mammal', mastered: false },
      { word: 'Dog', definition: 'A domesticated carnivorous mammal', mastered: false }
    ];
    saveDatabase();
    renderTable();
  }

  // Save database to localStorage
  function saveDatabase() {
    localStorage.setItem('vocabularyDB', JSON.stringify(vocabularyDB));
    alert('Database saved!');
  }

  // Clear database
  function clearDatabase() {
    if (confirm('Are you sure you want to clear the database?')) {
      vocabularyDB = [];
      saveDatabase();
      renderTable();
    }
  }

  // Render vocabulary table
  function renderTable() {
    const tbody = document.querySelector('#vocab-table tbody');
    tbody.innerHTML = '';
    vocabularyDB.forEach((entry, index) => {
      const tr = document.createElement('tr');

      const wordTd = document.createElement('td');
      wordTd.textContent = entry.word;
      tr.appendChild(wordTd);

      const defTd = document.createElement('td');
      defTd.textContent = entry.definition;
      tr.appendChild(defTd);

      const masteredTd = document.createElement('td');
      masteredTd.textContent = entry.mastered ? 'Yes' : 'No';
      tr.appendChild(masteredTd);

      const actionsTd = document.createElement('td');

      // Toggle mastered status
      const toggleBtn = document.createElement('button');
      toggleBtn.textContent = entry.mastered ? 'Unmark' : 'Mark as Mastered';
      toggleBtn.onclick = () => {
        vocabularyDB[index].mastered = !vocabularyDB[index].mastered;
        saveDatabase();
        renderTable();
      };
      actionsTd.appendChild(toggleBtn);

      // Delete button
      const deleteBtn = document.createElement('button');
      deleteBtn.textContent = 'Delete';
      deleteBtn.style.marginLeft = '5px';
      deleteBtn.onclick = () => {
        if (confirm(`Delete "${entry.word}"?`)) {
          vocabularyDB.splice(index, 1);
          saveDatabase();
          renderTable();
        }
      };
      actionsTd.appendChild(deleteBtn);

      tr.appendChild(actionsTd);
      tbody.appendChild(tr);
    });
  }

  // Add new vocabulary
  function addVocabulary() {
    const wordInput = document.getElementById('new-word');
    const defInput = document.getElementById('new-definition');
    const word = wordInput.value.trim();
    const definition = defInput.value.trim();

    if (word && definition) {
      vocabularyDB.push({ word, definition, mastered: false });
      saveDatabase();
      renderTable();
      wordInput.value = '';
      defInput.value = '';
    } else {
      alert('Please enter both word and definition.');
    }
  }

  // Start the test
  function startTest() {
    // Filter vocabulary based on exclude mastered option
    const excludeMastered = document.getElementById('exclude-mastered').checked;
    testWords = vocabularyDB.filter(entry => !excludeMastered || !entry.mastered);
    if (testWords.length === 0) {
      alert('No words available for testing. Please add words or change settings.');
      return;
    }
    // Shuffle the testWords array
    shuffleArray(testWords);
    score = 0;
    totalQuestions = testWords.length;
    document.getElementById('score').textContent = score;
    document.getElementById('test-area').classList.remove('hidden');
    document.getElementById('feedback').textContent = '';
    nextQuestion();
  }

  // Shuffle array in place
  function shuffleArray(array) {
    for (let i = array.length -1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i+1));
      [array[i], array[j]] = [array[j], array[i]];
    }
  }

  // Show next question
  function nextQuestion() {
    if (testWords.length === 0) {
      alert(`Test completed! Your score: ${score} out of ${totalQuestions}`);
      endTest();
      return;
    }
    currentWord = testWords.pop();
    document.getElementById('question').textContent = `Define: ${currentWord.word}`;
    document.getElementById('answer').value = '';
    document.getElementById('feedback').textContent = '';
  }

  // Submit answer
  function submitAnswer() {
    const userAnswer = document.getElementById('answer').value.trim().toLowerCase();
    const correctAnswer = currentWord.definition.toLowerCase();

    if (userAnswer === correctAnswer) {
      document.getElementById('feedback').textContent = 'Correct!';
      score++;
      document.getElementById('score').textContent = score;
    } else {
      document.getElementById('feedback').textContent = `Incorrect! Correct answer: ${currentWord.definition}`;
    }
    // Proceed to next question after a short delay
    setTimeout(nextQuestion, 1000);
  }

  // End test
  function endTest() {
    document.getElementById('test-area').classList.add('hidden');
  }

  // Initialize the app
  renderTable();

</script>

</body>
</html>
