    y: window.innerHeight - 50,
    width: 20,
    height: 60,
    color: '#555',
    velocityY: 0,
    isLaunching: false,
    flameOpacity: 1,
  };

  // Atmosphere layers (for visual effect)
  const atmosphereLayers = [
    { height: 200, color: 'rgba(135, 206, 250, 0.3)' }, // near ground
    { height: 200, color: 'rgba(100, 149, 237, 0.2)' }, // mid atmosphere
    { height: 200, color: 'rgba(70, 130, 180, 0.2)' },  // upper atmosphere
  ];

  // Function to draw the background sky
  function drawSky() {
    const gradient = ctx.createLinearGradient(0, 0, 0, canvas.height);
    gradient.addColorStop(0, '#87ceeb'); // sky blue
    gradient.addColorStop(1, '#ffffff'); // white
    ctx.fillStyle = gradient;
    ctx.fillRect(0, 0, canvas.width, canvas.height);
  }

  // Function to draw atmosphere layers
  function drawAtmosphere() {
    let yOffset = canvas.height;
    for (let layer of atmosphereLayers) {
      ctx.fillStyle = layer.color;
      ctx.fillRect(0, yOffset - layer.height, canvas.width, layer.height);
      yOffset -= layer.height;
    }
  }

  // Function to draw the rocket
  function drawRocket() {
    ctx.save();
    ctx.translate(rocket.x, rocket.y);
    // Draw rocket body
    ctx.fillStyle = rocket.color;
    ctx.fillRect(-rocket.width / 2, -rocket.height, rocket.width, rocket.height);
    // Draw nose cone
    ctx.beginPath();
    ctx.moveTo(0, -rocket.height - 10);
    ctx.lineTo(-rocket.width / 2, -rocket.height);
    ctx.lineTo(rocket.width / 2, -rocket.height);
    ctx.closePath();
    ctx.fill();

    // Draw flames if launching
    if (rocket.isLaunching) {
      ctx.globalAlpha = rocket.flameOpacity;
      ctx.fillStyle = 'orange';
      ctx.beginPath();
      ctx.moveTo(-rocket.width / 4, 0);
      ctx.lineTo(0, 20 + Math.random() * 10);
      ctx.lineTo(rocket.width / 4, 0);
      ctx.closePath();
      ctx.fill();
      ctx.globalAlpha = 1;
    }

    ctx.restore();
  }

  // Function to animate the launch
  function launchRocket() {
    if (rocket.isLaunching) return; // prevent multiple launches
    rocket.isLaunching = true;

    // Animate the rocket upward
