Certainly! To modify the sample rate of an input device (such as a microphone) in Windows, you typically need to interact with the Windows Core Audio APIs. These APIs are COM-based and are accessible via the Windows SDK.

Below is an example of C code that demonstrates how to set the sample rate of an input audio endpoint device. Note that this code uses the Windows Core Audio APIs, which are COM interfaces, so you'll need to include the appropriate headers and link against `Ole32.lib`.

**Important:** Modifying device settings like sample rate programmatically can be complex and may require administrative privileges or specific device support. Also, not all devices support changing the sample rate at runtime.

---

### Example: Set the Sample Rate of an Input Device in Windows

```c
#include <windows.h>
#include <mmdeviceapi.h>
#include <endpointvolume.h>
#include <audioclient.h>
#include <functiondiscoverykeys_devpkey.h>
#include <stdio.h>

// Link with Ole32.lib
#pragma comment(lib, "Ole32.lib")

// Helper function to initialize COM
HRESULT InitCOM() {
    return CoInitialize(NULL);
}

// Helper function to uninitialize COM
void UninitCOM() {
    CoUninitialize();
}

// Function to get the default audio capture device
HRESULT GetDefaultAudioCaptureDevice(IMMDevice **ppDevice) {
    HRESULT hr;
    IMMDeviceEnumerator *pEnumerator = NULL;

    hr = CoCreateInstance(&CLSID_MMDeviceEnumerator, NULL, CLSCTX_ALL,
                          &IID_IMMDeviceEnumerator, (void**)&pEnumerator);
    if (FAILED(hr)) {
        printf("Failed to create device enumerator: 0x%08x\n", hr);
        return hr;
    }

    hr = pEnumerator->lpVtbl->GetDefaultAudioEndpoint(pEnumerator,
                                                      eCapture,
                                                      eConsole,
                                                      ppDevice);
    pEnumerator->lpVtbl->Release(pEnumerator);
    return hr;
}

// Function to set the sample rate (via IAudioClient::Initialize)
HRESULT SetDeviceSampleRate(IMMDevice *pDevice, UINT32 desiredSampleRate) {
    HRESULT hr;
    IAudioClient *pAudioClient = NULL;
    WAVEFORMATEX *pwfx = NULL;

    // Activate the IAudioClient interface
    hr = pDevice->lpVtbl->Activate(pDevice, &IID_IAudioClient, CLSCTX_ALL, NULL, (void**)&pAudioClient);
    if (FAILED(hr)) {
        printf("Failed to activate IAudioClient: 0x%08x\n", hr);
        return hr;
    }

    // Get the device's default format
    hr = pAudioClient->lpVtbl->GetMixFormat(pAudioClient, &pwfx);
    if (FAILED(hr)) {
        printf("Failed to get mix format: 0x%08x\n", hr);
        pAudioClient->lpVtbl->Release(pAudioClient);
        return hr;
    }

    // Modify the sample rate in the WAVEFORMATEX structure
    pwfx->nSamplesPerSec = desiredSampleRate;

    // Initialize the audio client with the new format
    // Note: The Initialize method requires specific parameters.
    // For shared mode:
    hr = pAudioClient->lpVtbl->Initialize(pAudioClient,
                                          AUDCLNT_SHAREMODE_SHARED,
                                          0,
                                          0,
                                          pwfx,
                                          NULL);
    if (FAILED(hr)) {
        printf("Failed to initialize audio client with new format: 0x%08x\n", hr);
        CoTaskMemFree(pwfx);
        pAudioClient->lpVtbl->Release(pAudioClient);
        return hr;
    }

    printf("Successfully set sample rate to %u Hz\n", desiredSampleRate);

    // Cleanup
    CoTaskMemFree(pwfx);
    pAudioClient->lpVtbl->Release(pAudioClient);
    return S_OK;
}

int main() {
    HRESULT hr;

    hr = InitCOM();
    if (FAILED(hr)) {
        printf("COM initialization failed: 0x%08x\n", hr);
        return -1;
    }

    IMMDevice *pDevice = NULL;
    hr = GetDefaultAudioCaptureDevice(&pDevice);
    if (FAILED(hr)) {
        printf("Failed to get default capture device: 0x%08x\n", hr);
        UninitCOM();
        return -1;
    }

    // Set desired sample rate, e.g., 48000 Hz
    UINT32 desiredSampleRate = 48000;

    hr = SetDeviceSampleRate(pDevice, desiredSampleRate);
    if (FAILED(hr)) {
        printf("Failed to set sample rate: 0x%08x\n", hr);
    } else {
        printf("Sample rate modification attempted.\n");
    }

    pDevice->lpVtbl->Release(pDevice);
    UninitCOM();
    return 0;
}
```

