    { label: '27', color: '#FF0000' },
    { label: '13', color: '#000000' },
    { label: '36', color: '#FF0000' },
    { label: '11', color: '#000000' },
    { label: '30', color: '#FF0000' },
    { label: '8', color: '#000000' },
    { label: '23', color: '#FF0000' },
    { label: '10', color: '#000000' },
    { label: '5', color: '#FF0000' },
    { label: '24', color: '#000000' },
    { label: '16', color: '#FF0000' },
    { label: '33', color: '#000000' },
    { label: '1', color: '#FF0000' },
    { label: '20', color: '#000000' },
    { label: '14', color: '#FF0000' },
    { label: '31', color: '#000000' },
    { label: '9', color: '#FF0000' },
    { label: '22', color: '#000000' },
    { label: '18', color: '#FF0000' },
    { label: '29', color: '#000000' },
    { label: '7', color: '#FF0000' },
    { label: '28', color: '#000000' },
    { label: '12', color: '#FF0000' },
    { label: '35', color: '#000000' },
    { label: '3', color: '#FF0000' },
    { label: '26', color: '#000000' }
  ];

  const numSegments = segments.length;
  const centerX = 250;
  const centerY = 250;
  const radius = 200;

  let currentAngle = 0; // in radians
  let isSpinning = false;
  let spinAnimationId = null;

  // Function to draw the wheel
  function drawWheel(rotationAngle = 0) {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    const anglePerSegment = (2 * Math.PI) / numSegments;

    for (let i = 0; i < numSegments; i++) {
      const startAngle = i * anglePerSegment + rotationAngle;
      const endAngle = startAngle + anglePerSegment;

      // Draw segment
      ctx.beginPath();
      ctx.moveTo(centerX, centerY);
      ctx.arc(centerX, centerY, radius, startAngle, endAngle);
      ctx.closePath();
      ctx.fillStyle = segments[i].color;
      ctx.fill();

      // Draw label
      ctx.save();
      ctx.translate(centerX, centerY);
      ctx.rotate(startAngle + anglePerSegment / 2);
      ctx.textAlign = "right";
      ctx.fillStyle = "#fff";
      ctx.font = "bold 16px Arial";

      // Position label at a radius slightly less than wheel radius
      ctx.translate(radius - 30, 0);
      ctx.rotate(Math.PI / 2); // Rotate text to be horizontal
      ctx.fillText(segments[i].label, 0, 0);
      ctx.restore();
    }

    // Draw pointer (arrow) at top center
    drawPointer();
  }

  // Function to draw the pointer
  function drawPointer() {
    ctx.save();
    ctx.translate(centerX, centerY);
    ctx.fillStyle = "#fff";
    ctx.beginPath();
    ctx.moveTo(0, -radius - 10);
    ctx.lineTo(-15, -radius + 10);
    ctx.lineTo(15, -radius + 10);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }

  // Function to start spinning
  function spinWheel() {
    if (isSpinning) return; // prevent multiple spins
    isSpinning = true;
    resultDiv.textContent = '';

    // Randomly determine how many rotations and final position
    const minRotations = 3; // minimum full rotations
    const maxRotations = 6; // maximum full rotations
    const rotations = Math.floor(Math.random() * (maxRotations - minRotations + 1)) + minRotations;

    // Randomly select a segment as the winning segment
    const targetIndex = Math.floor(Math.random() * numSegments);
    const anglePerSegment = (2 * Math.PI) / numSegments;

    // Calculate the final angle to land on the target segment
    // Pointer is at 0 radians (top), so we want the segment's middle to align with pointer
    const targetSegmentStart = targetIndex * anglePerSegment;
    const targetSegmentMid = targetSegmentStart + anglePerSegment / 2;

    // Final angle in radians (negative because canvas rotation is clockwise)
    const finalRotation = rotations * 2 * Math.PI + (Math.PI / 2) - targetSegmentMid;

    // Animate the spin
    const duration = 4000; // in ms
    const startTime = performance.now();

    function animate(currentTime) {
      const elapsed = currentTime - startTime;
      if (elapsed >= duration) {
        // End of animation
        currentAngle = finalRotation;
        drawWheel(currentAngle);
        isSpinning = false;
        // Display result
        const winningSegment = segments[targetIndex];
        resultDiv.textContent = `Winning Number: ${winningSegment.label}`;
        return;
      }

      // Ease out animation (deceleration)
      const progress = elapsed / duration;
      const easedProgress = 1 - Math.pow(1 - progress, 3); // cubic easing out

      const currentRotation = easedProgress * finalRotation;
      drawWheel(currentRotation);
      spinAnimationId = requestAnimationFrame(animate);
    }

    requestAnimationFrame(animate);
  }

  // Initial draw
  drawWheel();

  // Event listener for spin button
  document.getElementById('spinButton').addEventListener('click', spinWheel);
</script>

</body>
</html>
```

### How it works:
- The wheel is drawn on an HTML `<canvas>` element with segments representing roulette numbers.
- When you click the "Spin the Wheel" button, the wheel spins with an animated deceleration.
- After spinning, it displays the winning number based on where the wheel stops.

### Customization:
- You can modify the `segments` array to include different numbers or colors.
- Adjust the `duration` variable for faster or slower spins.
- Enhance visuals or add sound effects as desired.

