  window.addEventListener('resize', resize);
  resize();

  // Particle class
  class Particle {
    constructor(x, y) {
      this.x = x;
      this.y = y;
      this.vx = (Math.random() - 0.5) * 2;
      this.vy = (Math.random() - 0.5) * 2;
      this.radius = 8 + Math.random() * 4;
      this.mass = this.radius * 0.1;
      this.color = `hsl(${Math.random() * 360}, 70%, 60%)`;
    }

    update() {
      // Apply gravity
      this.vy += 0.2;

      // Move particle
      this.x += this.vx;
      this.y += this.vy;

      // Collide with walls
      if (this.x - this.radius < 0) {
        this.x = this.radius;
        this.vx *= -0.8;
      } else if (this.x + this.radius > canvas.width) {
        this.x = canvas.width - this.radius;
        this.vx *= -0.8;
      }
      if (this.y - this.radius < 0) {
        this.y = this.radius;
        this.vy *= -0.8;
      } else if (this.y + this.radius > canvas.height) {
        this.y = canvas.height - this.radius;
        this.vy *= -0.8;
      }
    }

    draw() {
      ctx.beginPath();
      ctx.arc(this.x, this.y, this.radius, 0, Math.PI * 2);
      ctx.fillStyle = this.color;
      ctx.fill();
    }
  }

  // Generate particles
  const particles = [];
  const NUM_PARTICLES = 50;
  for (let i = 0; i < NUM_PARTICLES; i++) {
    particles.push(new Particle(
      Math.random() * canvas.width,
      Math.random() * canvas.height
    ));
  }

  // Function to connect particles with lines based on proximity
  function connectParticles() {
    for (let i = 0; i < particles.length; i++) {
      for (let j = i + 1; j < particles.length; j++) {
        const p1 = particles[i];
        const p2 = particles[j];
        const dx = p1.x - p2.x;
        const dy = p1.y - p2.y;
        const dist = Math.hypot(dx, dy);
        const maxDist = 100;
        if (dist < maxDist) {
          ctx.strokeStyle = `hsla(200, 70%, 50%, ${(maxDist - dist) / maxDist * 0.5})`;
          ctx.lineWidth = 1;
          ctx.beginPath();
          ctx.moveTo(p1.x, p1.y);
          ctx.lineTo(p2.x, p2.y);
          ctx.stroke();
        }
      }
    }
  }

  // Main animation loop
  function animate() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Update particles
    for (let p of particles) {
      p.update();
    }

    // Connect particles with lines
    connectParticles();

    // Draw particles
    for (let p of particles) {
      p.draw();
    }

    requestAnimationFrame(animate);
  }

  // Initialize with some particles clustered in the center
  for (let i = 0; i < NUM_PARTICLES; i++) {
