      name: "Cookie Empire",
      description: "Generate 100 points per second",
      cost: 5000,
      purchased: false,
      effect: () => {
        passivePoints += 100;
      },
      unlockAt: 5000
    }
  ];

  const pointsDiv = document.getElementById('points');
  const upgradesDiv = document.getElementById('upgrades');

  // Initialize upgrade buttons
  upgrades.forEach((upgrade, index) => {
    const btn = document.createElement('button');
    btn.className = 'upgrade';
    btn.innerHTML = `<strong>${upgrade.name}</strong><br/>Cost: ${upgrade.cost} points<br/>${upgrade.description}`;
    btn.disabled = true; // Initially disabled until unlocked
    btn.addEventListener('click', () => {
      if (points >= upgrade.cost && !upgrade.purchased) {
        points -= upgrade.cost;
        upgrade.purchased = true;
        upgrade.effect();
        btn.disabled = true;
        updatePoints();
      }
    });
    upgrade.button = btn; // Store reference for later
    upgradesDiv.appendChild(btn);
  });

  // Function to update points display
  function updatePoints() {
    pointsDiv.innerText = `Points: ${points}`;
  }

  // Handle cookie click
  const cookie = document.getElementById('cookie');
  cookie.addEventListener('click', () => {
    points += pointsPerClick;
    updatePoints();
    checkUnlocks();
  });

  // Check for unlocks
  function checkUnlocks() {
    upgrades.forEach((upgrade) => {
      if (!upgrade.purchased && points >= upgrade.unlockAt) {
        // Unlock the upgrade
        upgrade.button.disabled = false;
      }
    });
  }

  // Passive points generation
  setInterval(() => {
    if (passivePoints > 0) {
      points += passivePoints;
      updatePoints();
      checkUnlocks();
    }
  }, 1000); // Every second

  // Optional: Add some visual feedback when clicking
  // (e.g., animate cookie or show points gained)

  // Initialize display
  updatePoints();
</script>

</body>
</html>
```

---

### How it works:

- **Clicking the cookie** increases your points based on `pointsPerClick`.
- **Points are displayed** prominently.
- **Upgrades** are initially disabled and become available when you reach their unlock thresholds.
- **Purchasing an upgrade** deducts points and applies its effect:
  - Some upgrades increase passive points generation (`passivePoints`).
  - Others increase points per click.
- **Passive points** are added every second, simulating automatic generation.

---

### Customization:
- You can add more upgrades with different effects and unlock thresholds.
- Use different images for the cookie.
- Enhance visuals with animations or sounds.

