Certainly! Here's a TypeScript example demonstrating how to use `http-middleware-proxy` to modify both POST request data and response data, supporting JSON and NDJSON formats.

First, ensure you have the necessary dependencies installed:

```bash
npm install http-middleware-proxy
```

Now, here's the code snippet:

```typescript
import { createProxyMiddleware, RequestHandler } from 'http-middleware-proxy';
import * as http from 'http';

// Helper function to parse NDJSON stream into array of objects
function parseNDJSON(stream: NodeJS.ReadableStream): Promise<any[]> {
  return new Promise((resolve, reject) => {
    const chunks: string[] = [];
    stream.setEncoding('utf8');

    stream.on('data', (chunk) => {
      chunks.push(chunk);
    });

    stream.on('end', () => {
      const data = chunks.join('');
      const lines = data.split('\n').filter(line => line.trim() !== '');
      const objects = lines.map(line => JSON.parse(line));
      resolve(objects);
    });

    stream.on('error', reject);
  });
}

// Helper function to serialize array of objects into NDJSON stream
function serializeNDJSON(objects: any[]): string {
  return objects.map(obj => JSON.stringify(obj)).join('\n') + '\n';
}

// Middleware to modify request body
const modifyRequestBody: RequestHandler = (req, res, next) => {
  if (req.method === 'POST') {
    if (req.headers['content-type']?.includes('application/json')) {
      // For JSON POST data
      let bodyData = '';

      req.on('data', chunk => {
        bodyData += chunk;
      });

      req.on('end', () => {
        try {
          const jsonData = JSON.parse(bodyData);
          // Modify the JSON data as needed
          jsonData.modified = true;

          // Replace request body with modified data
          req.headers['content-length'] = Buffer.byteLength(JSON.stringify(jsonData)).toString();
          req.body = JSON.stringify(jsonData);
          next();
        } catch (err) {
          next(err);
        }
      });
    } else {
      // Handle other content types if necessary
      next();
    }
  } else {
    next();
  }
};

// Middleware to modify response data
const modifyResponseData: RequestHandler = (req, res, next) => {
  // Intercept the response
  const originalWrite = res.write;
  const originalEnd = res.end;

  const chunks: Buffer[] = [];

  res.write = (chunk: any, ...args: any[]) => {
    chunks.push(Buffer.from(chunk));
  };

  res.end = async (chunk?: any, ...args: any[]) => {
    if (chunk) {
      chunks.push(Buffer.from(chunk));
    }

    const bodyBuffer = Buffer.concat(chunks);
    const contentType = res.getHeader('content-type');

    if (contentType && typeof contentType === 'string') {
      if (contentType.includes('application/json')) {
        // JSON response
        const bodyString = bodyBuffer.toString('utf8');
        let data = JSON.parse(bodyString);
        // Modify response data
        if (Array.isArray(data)) {
          data.push({ modified: true });
        } else if (typeof data === 'object') {
          data.modified = true;
        }
        const modifiedBody = JSON.stringify(data);
        res.setHeader('content-length', Buffer.byteLength(modifiedBody));
        originalWrite.call(res, modifiedBody);
        originalEnd.call(res);
      } else if (contentType.includes('application/x-ndjson') || contentType.includes('application/ndjson')) {
        // NDJSON response
        const stream = require('stream');
        const readable = new stream.Readable();
        readable._read = () => {}; // no-op
        readable.push(bodyBuffer);
        readable.push(null);

        try {
          const objects = await parseNDJSON(readable);
          // Modify objects
          objects.push({ modified: true });
          const modifiedNDJSON = serializeNDJSON(objects);
          res.setHeader('content-length', Buffer.byteLength(modifiedNDJSON));
          originalWrite.call(res, modifiedNDJSON);
          originalEnd.call(res);
        } catch (err) {
          // fallback: send original data if parsing fails
          res.setHeader('content-length', bodyBuffer.length);
          originalWrite.call(res, bodyBuffer);
          originalEnd.call(res);
        }
      } else {
        // Other content types, pass through
        res.setHeader('content-length', bodyBuffer.length);
        originalWrite.call(res, bodyBuffer);
        originalEnd.call(res);
      }
    } else {
      // No content-type header, pass through
      res.setHeader('content-length', bodyBuffer.length);
      originalWrite.call(res, bodyBuffer);
      originalEnd.call(res);
    }
  };

  next();
};

// Create the proxy middleware with modifications
const proxy = createProxyMiddleware('http://target-server.com', {
  requestMiddleware: [modifyRequestBody],
  responseMiddleware: [modifyResponseData],
});

// Create an HTTP server that uses the proxy
const server = http.createServer((req, res) => {
  proxy(req, res, (err: any) => {
    if (err) {
      res.statusCode = 500;
      res.end(`Error: ${err.message}`);
    }
  });
});

const PORT = 3000;
server.listen(PORT, () => {
  console.log(`Proxy server listening on port ${PORT}`);
});
```

### Explanation:
- **Request modification**:
  - Checks if the method is POST and content type is JSON.
  - Parses the incoming JSON, modifies it (adds a `modified: true` property), and updates the request body.
- **Response modification**:
  - Intercepts the response data by overriding `res.write` and `res.end`.
  - Checks the `Content-Type` header.
  - For JSON responses, parses, modifies, and rewrites the JSON.
  - For NDJSON responses, parses the stream into objects, modifies, and serializes back.
- **NDJSON handling**:
  - Uses helper functions `parseNDJSON` and `serializeNDJSON` to handle NDJSON streams.

### Notes:
- Adjust the target URL (`http://target-server.com`) as needed.
- This example assumes the server responds with either JSON or NDJSON; you can extend it to handle other formats.
- Error handling is minimal; enhance as needed for production use.

