    background-color: #45a049;
  }
</style>
</head>
<body>

<h1>Tic Tac Toe</h1>
<div id="game">
  <div class="cell" data-index="0"></div>
  <div class="cell" data-index="1"></div>
  <div class="cell" data-index="2"></div>
  <div class="cell" data-index="3"></div>
  <div class="cell" data-index="4"></div>
  <div class="cell" data-index="5"></div>
  <div class="cell" data-index="6"></div>
  <div class="cell" data-index="7"></div>
  <div class="cell" data-index="8"></div>
</div>
<div id="status"></div>
<button id="reset">Reset Game</button>

<script>
  // Initialize game state
  const cells = document.querySelectorAll('.cell');
  const statusDiv = document.getElementById('status');
  const resetButton = document.getElementById('reset');

  let board = Array(9).fill(null); // null, 'X', or 'O'
  let currentPlayer = 'X';
  let gameActive = true;

  const winningCombinations = [
    [0,1,2],
    [3,4,5],
    [6,7,8],
    [0,3,6],
    [1,4,7],
    [2,5,8],
    [0,4,8],
    [2,4,6]
  ];

  // Function to handle cell clicks
  function handleCellClick(e) {
    const index = parseInt(e.target.getAttribute('data-index'));
    if (!gameActive || board[index]) {
      return; // Ignore if game over or cell already filled
    }

    // Update board state
    board[index] = currentPlayer;
    e.target.textContent = currentPlayer;

    // Check for win
    if (checkWin()) {
      statusDiv.textContent = `Player ${currentPlayer} wins!`;
      gameActive = false;
      return;
    }

    // Check for draw
    if (board.every(cell => cell)) {
      statusDiv.textContent = "It's a draw!";
      gameActive = false;
      return;
    }

    // Switch players
    currentPlayer = currentPlayer === 'X' ? 'O' : 'X';
    statusDiv.textContent = `Player ${currentPlayer}'s turn`;
  }

  // Function to check for a win
  function checkWin() {
    return winningCombinations.some(combination => {
      const [a, b, c] = combination;
      return board[a] && board[a] === board[b] && board[a] === board[c];
    });
  }

  // Function to reset the game
  function resetGame() {
    board.fill(null);
    cells.forEach(cell => (cell.textContent = ''));
    currentPlayer = 'X';
    gameActive = true;
    statusDiv.textContent = `Player ${currentPlayer}'s turn`;
  }

  // Attach event listeners
  cells.forEach(cell => cell.addEventListener('click', handleCellClick));
  resetButton.addEventListener('click', resetGame);

  // Initialize status
  statusDiv.textContent = `Player ${currentPlayer}'s turn`;
</script>

</body>
</html>
```

### How it works:
- The game board is a 3x3 grid of clickable cells.
- Players take turns clicking empty cells to place their mark (`X` or `O`).
- The game checks for a winner after each move.
- If a player wins or all cells are filled (draw), the game ends.
- The "Reset Game" button restarts the game.

