const canvas = document.getElementById('canvas');
const ctx = canvas.getContext('2d');

const cropBtn = document.getElementById('cropBtn');
const rotateLeftBtn = document.getElementById('rotateLeftBtn');
const rotateRightBtn = document.getElementById('rotateRightBtn');
const flipHBtn = document.getElementById('flipHBtn');
const flipVBtn = document.getElementById('flipVBtn');
const brightnessRange = document.getElementById('brightnessRange');
const saveBtn = document.getElementById('saveBtn');

let images = []; // Array of {file, img, thumbnail}
let currentImage = null; // {file, img, thumbnail}
let originalImage = null; // Original Image object
let currentTransform = {
  rotation: 0,
  flipH: 1,
  flipV: 1,
  brightness: 0
};
let cropping = false;
let cropStartX = 0;
let cropStartY = 0;
let cropEndX = 0;
let cropEndY = 0;

// Handle multiple image uploads
imageUpload.addEventListener('change', (e) => {
  const files = Array.from(e.target.files);
  files.forEach(file => {
    const reader = new FileReader();
    reader.onload = (event) => {
      const img = new Image();
      img.onload = () => {
        images.push({file, img});
        addThumbnail(img);
        if (!currentImage) {
          selectImage(img);
        }
      };
      img.src = event.target.result;
    };
    reader.readAsDataURL(file);
  });
});

// Add thumbnail preview
function addThumbnail(img) {
  const thumb = document.createElement('img');
  thumb.src = img.src;
  thumb.className = 'thumbnail';
  thumb.title = 'Click to select';
  thumb.onclick = () => {
    selectImage(img);
  };
  thumbnailsContainer.appendChild(thumb);
}

// Select an image to edit
function selectImage(img) {
  currentImage = {img};
  resetTransform();
  drawImage();
}

// Reset transformations
function resetTransform() {
  currentTransform = {
    rotation: 0,
    flipH: 1,
    flipV: 1,
    brightness: 0
  };
  brightnessRange.value = 0;
}

// Draw image on canvas with current transformations
function drawImage() {
  if (!currentImage) return;
  const img = currentImage.img;
  // Set canvas size to image size
  canvas.width = img.width;
  canvas.height = img.height;

  ctx.save();
  // Clear canvas
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Apply transformations
  ctx.translate(canvas.width / 2, canvas.height / 2);
  ctx.rotate(currentTransform.rotation * Math.PI / 180);
  ctx.scale(currentTransform.flipH, currentTransform.flipV);
  ctx.translate(-canvas.width / 2, -canvas.height / 2);

  // Draw image
  ctx.drawImage(img, 0, 0);

  ctx.restore();

  applyBrightness();
}

// Apply brightness filter
function applyBrightness() {
  const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
  const data = imageData.data;
  const brightness = parseInt(brightnessRange.value);
  for (let i = 0; i < data.length; i += 4) {
    data[i] += brightness;     // Red
    data[i + 1] += brightness; // Green
    data[i + 2] += brightness; // Blue
  }
  ctx.putImageData(imageData, 0, 0);
}

// Event listeners for controls
document.getElementById('cropBtn').addEventListener('click', () => {
  cropping = !cropping;
  if (cropping) {
    alert('Click and drag on the image to crop.');
  }
});

document.getElementById('rotateLeftBtn').addEventListener('click', () => {
  currentTransform.rotation -= 90;
  drawImage();
});

document.getElementById('rotateRightBtn').addEventListener('click', () => {
  currentTransform.rotation += 90;
  drawImage();
});

document.getElementById('flipHBtn').addEventListener('click', () => {
  currentTransform.flipH *= -1;
  drawImage();
});

document.getElementById('flipVBtn').addEventListener('click', () => {
  currentTransform.flipV *= -1;
  drawImage();
});

brightnessRange.addEventListener('input', () => {
  drawImage();
});

// Canvas mouse events for cropping
let isDragging = false;
let cropRect = {};

canvas.addEventListener('mousedown', (e) => {
  if (!cropping) return;
  isDragging = true;
  cropStartX = e.offsetX;
  cropStartY = e.offsetY;
});

canvas.addEventListener('mouseup', (e) => {
  if (!cropping || !isDragging) return;
  isDragging = false;
  cropEndX = e.offsetX;
  cropEndY = e.offsetY;
  performCrop();
  cropping = false;
});

canvas.addEventListener('mousemove', (e) => {
  if (cropping && isDragging) {
    // Optional: show cropping rectangle
    const rectX = Math.min(cropStartX, e.offsetX);
    const rectY = Math.min(cropStartY, e.offsetY);
    const rectWidth = Math.abs(cropStartX - e.offsetX);
    const rectHeight = Math.abs(cropStartY - e.offsetY);
    drawImage();
    ctx.strokeStyle = 'red';
    ctx.lineWidth = 2;
    ctx.strokeRect(rectX, rectY, rectWidth, rectHeight);
  }
});

// Perform cropping
function performCrop() {
  const x = Math.min(cropStartX, cropEndX);
  const y = Math.min(cropStartY, cropEndY);
  const width = Math.abs(cropStartX - cropEndX);
  const height = Math.abs(cropStartY - cropEndY);

  // Create a temporary canvas to hold the cropped image
  const tempCanvas = document.createElement('canvas');
  tempCanvas.width = width;
  tempCanvas.height = height;
  const tempCtx = tempCanvas.getContext('2d');

  // Draw the cropped area
  tempCtx.drawImage(canvas, x, y, width, height, 0, 0, width, height);

  // Update currentImage with the cropped image
  const croppedImg = new Image();
  croppedImg.onload = () => {
    currentImage.img = croppedImg;
    resetTransform();
    drawImage();
  };
  croppedImg.src = tempCanvas.toDataURL();
}

// Save the meme
