### Complete C# Example

```csharp
using System;
using System.IO;
using System.Collections.Generic;
using SAPbobsCOM; // Reference to SAP Business One DI API

namespace SAPB1SpecialPrices
{
    class Program
    {
        // Define a class to hold CSV data
        public class SpecialPrice
        {
            public string ItemCode { get; set; }
            public int PriceList { get; set; }
            public double MinQuantity { get; set; }
            public double Price { get; set; }
        }

        static void Main(string[] args)
        {
            string csvFilePath = @"C:\Path\To\Your\special_prices.csv";

            // Read CSV data
            List<SpecialPrice> specialPrices = ReadCsv(csvFilePath);

            // Initialize SAP DI API connection
            Company oCompany = new Company();

            try
            {
                // Connect to SAP Business One
                oCompany.Server = "YOUR_SERVER";
                oCompany.DbServerType = BoDataServerTypes.dst_MSSQL2014; // Adjust as needed
                oCompany.CompanyDB = "YOUR_COMPANY_DB";
                oCompany.UserName = "manager"; // Your username
                oCompany.Password = "password"; // Your password
                oCompany.DbUserName = "sa"; // DB user
                oCompany.DbPassword = "password"; // DB password

                int connectResult = oCompany.Connect();
                if (connectResult != 0)
                {
                    Console.WriteLine("Failed to connect to SAP Business One. Error: " + oCompany.GetLastErrorDescription());
                    return;
                }
                Console.WriteLine("Connected to SAP Business One.");

                // Get Special Prices object
                SpecialPrices oSpecialPrices = (SpecialPrices)oCompany.GetBusinessObject(BoObjectTypes.oSpecialPrices);

                foreach (var sp in specialPrices)
                {
                    // Search for existing special price entry
                    bool exists = false;
                    oSpecialPrices.GetByKey(sp.ItemCode, sp.PriceList, sp.MinQuantity);
                    if (oSpecialPrices.IsExists)
                    {
                        exists = true;
                        // Update existing record
                        oSpecialPrices.Price = sp.Price;
                        Console.WriteLine($"Updating special price for Item: {sp.ItemCode}, PriceList: {sp.PriceList}, MinQty: {sp.MinQuantity}");
                    }
                    else
                    {
                        // Add new record
                        oSpecialPrices.ItemCode = sp.ItemCode;
                        oSpecialPrices.PriceList = sp.PriceList;
                        oSpecialPrices.MinQuantity = sp.MinQuantity;
                        oSpecialPrices.Price = sp.Price;
                        Console.WriteLine($"Adding new special price for Item: {sp.ItemCode}, PriceList: {sp.PriceList}, MinQty: {sp.MinQuantity}");
                    }

                    // Save changes
                    int res = oSpecialPrices.Add();
                    if (res != 0)
                    {
                        Console.WriteLine($"Error adding/updating special price for Item: {sp.ItemCode}. Error: " + oCompany.GetLastErrorDescription());
                    }
                }

                Console.WriteLine("Special prices processing completed.");
            }
            catch (Exception ex)
            {
                Console.WriteLine("Exception: " + ex.Message);
            }
            finally
            {
                // Disconnect
                if (oCompany.Connected)
                {
                    oCompany.Disconnect();
                }
            }
        }

        static List<SpecialPrice> ReadCsv(string filePath)
        {
            var list = new List<SpecialPrice>();
            try
            {
                using (var reader = new StreamReader(filePath))
                {
                    string headerLine = reader.ReadLine(); // Skip header
                    while (!reader.EndOfStream)
                    {
                        var line = reader.ReadLine();
                        var values = line.Split(',');

                        if (values.Length >= 4)
                        {
                            var sp = new SpecialPrice
                            {
                                ItemCode = values[0].Trim(),
                                PriceList = int.Parse(values[1].Trim()),
                                MinQuantity = double.Parse(values[2].Trim()),
                                Price = double.Parse(values[3].Trim())
                            };
                            list.Add(sp);
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine("Error reading CSV: " + ex.Message);
            }
            return list;
        }
    }
}
```

---

### Notes:
- Replace `"YOUR_SERVER"`, `"YOUR_COMPANY_DB"`, `"manager"`, and `"password"` with your SAP B1 environment details.
- Adjust `BoDataServerTypes.dst_MSSQL2014` to match your database server type.
- Make sure the DI API COM reference (`SAPbobsCOM`) is added to your project.
- The code reads the CSV, then for each record:
  - Checks if a special price entry exists.
  - Updates it if it exists.
  - Adds it if it doesn't.
- Error handling is included for connection and data operations.

---

### Additional Tips:
- Always test in a development environment before running in production.
- Backup your database before bulk updates.
- Consider adding logging or more sophisticated error handling as needed.

