<svg id="cradle" width="800" height="400"></svg>

<script>
  const svg = document.getElementById('cradle');

  // Configuration
  const NUM_SPHERES = 5;
  const SPHERE_RADIUS = 20;
  const SPACING = 50; // space between spheres
  const STRING_LENGTH = 150; // length of suspension strings
  const FRAME_WIDTH = 800;
  const FRAME_HEIGHT = 400;

  // Positions
  const cradleX = (FRAME_WIDTH - (NUM_SPHERES - 1) * SPACING) / 2;
  const cradleY = 50; // top position of the frame

