    circle.setAttribute("cx", spheres[i].x);
    circle.setAttribute("cy", spheres[i].y);
    circle.setAttribute("r", SPHERE_RADIUS);
    circle.setAttribute("fill", "#bbb");
    circle.setAttribute("stroke", "#999");
    circle.setAttribute("stroke-width", "2");
    if (i === 0) {
      circle.classList.add("draggable");
    }
    svg.appendChild(circle);
    spheres[i].element = circle;
  }

  // Helper function to update the SVG elements
