    for (let i = 0; i < NUM_SPHERES; i++) {
      const s = spheres[i];
      // Update string
      const line = strings[i].element;
      line.setAttribute("x1", cradleX + i * SPACING);
      line.setAttribute("y1", cradleY);
      line.setAttribute("x2", s.x);
      line.setAttribute("y2", s.y);

      // Update sphere position
      s.element.setAttribute("cx", s.x);
      s.element.setAttribute("cy", s.y);
