  }

  // Physics simulation: constrain spheres to pendulum motion
  function simulate() {
    for (let i = 0; i < NUM_SPHERES; i++) {
      const s = spheres[i];

      if (i === 0 && isDragging) {
        // During dragging, position is controlled by mouse
        continue;
      }

      // Calculate the vector from the pivot point to the sphere
      const dx = s.x - (cradleX + i * SPACING);
      const dy = s.y - cradleY;
      const dist = Math.sqrt(dx * dx + dy * dy);
      const diff = dist - STRING_LENGTH;

      if (dist !== 0) {
        // Correct position to maintain string length
        const correction = (diff / dist) * 0.2; // correction factor
        s.x -= dx * correction;
        s.y -= dy * correction;
