    }

    // Handle collisions (simple elastic collisions between spheres)
    for (let i = 0; i < NUM_SPHERES - 1; i++) {
      const s1 = spheres[i];
      const s2 = spheres[i + 1];

      const dx = s2.x - s1.x;
      const dy = s2.y - s1.y;
      const dist = Math.sqrt(dx * dx + dy * dy);
      if (dist < s1.radius + s2.radius && dist !== 0) {
        // Overlap detected, resolve collision
        const overlap = 0.5 * (dist - s1.radius - s2.radius);
        const nx = dx / dist;
        const ny = dy / dist;

        s1.x -= overlap * nx;
        s1.y -= overlap * ny;
        s2.x += overlap * nx;
        s2.y += overlap * ny;

