        const v2After = v1;

        s1.vx += (v1After - v1) * nx;
        s1.vy += (v1After - v1) * ny;
        s2.vx += (v2After - v2) * nx;
        s2.vy += (v2After - v2) * ny;
      }
    }
  }

  // Animation loop
  function animate() {
    simulate();
    updateGraphics();
    requestAnimationFrame(animate);
  }

  // Event listeners for dragging
  svg.addEventListener('mousedown', (e) => {
    const rect = svg.getBoundingClientRect();
    const mouseX = e.clientX - rect.left;
    const mouseY = e.clientY - rect.top;

