      currentMouse.y = e.clientY - rect.top;

      // Update sphere position directly
      const s = spheres[dragSphereIndex];
      s.x = currentMouse.x;
      s.y = currentMouse.y;

      // Calculate velocity based on movement
      s.vx = (s.x - dragStart.x) / timeStep;
      s.vy = (s.y - dragStart.y) / timeStep;

      dragStart.x = s.x;
      dragStart.y = s.y;
    }
  });

  svg.addEventListener('mouseup', () => {
    if (isDragging) {
      isDragging = false;
    }
  });

  // Optional: release sphere with physics
  document.addEventListener('mouseup', () => {
    if (isDragging) {
      isDragging = false;
    }
  });

  // Start animation
  animate();

</script>
</body>
</html>
```

