    private ComboBox<String> cmbPatients;
    private Button btnSave;

    public MedicalHistory() {
        listView = new ListView<>();
        refreshPatientList();

        txtHistory = new TextArea();
        txtHistory.setPrefRowCount(10);

        cmbPatients = new ComboBox<>();
        refreshPatientList();

        Button btnLoad = new Button("Load History");
        btnLoad.setOnAction(e -> loadHistory());

        btnSave = new Button("Save History");
        btnSave.setOnAction(e -> saveHistory());

        HBox topBox = new HBox(10, new Label("Select Patient:"), cmbPatients, btnLoad);
        topBox.setPadding(new Insets(10));

        view = new VBox(10, topBox, txtHistory, btnSave);
        view.setPadding(new Insets(10));
    }

    public Pane getView() {
        return view;
    }

    private void refreshPatientList() {
        ObservableList<String> patientNames = FXCollections.observableArrayList();
        for (Patient p : DataModel.patients) {
            patientNames.add(p.id + " - " + p.name);
        }
        cmbPatients.setItems(patientNames);
    }

    private void loadHistory() {
        String selected = cmbPatients.getSelectionModel().getSelectedItem();
        if (selected != null) {
            String patientId = selected.split(" - ")[0];
            for (MedicalRecord mr : DataModel.medicalHistories) {
                if (mr.patientId.equals(patientId)) {
                    txtHistory.setText(mr.history);
                    return;
                }
            }
            txtHistory.setText("");
        }
    }

    private void saveHistory() {
        String selected = cmbPatients.getSelectionModel().getSelectedItem();
        if (selected != null) {
            String patientId = selected.split(" - ")[0];
            String historyText = txtHistory.getText();

            // Check if record exists
            for (MedicalRecord mr : DataModel.medicalHistories) {
                if (mr.patientId.equals(patientId)) {
                    mr.history = historyText;
                    return;
                }
            }
            // Else add new
            DataModel.medicalHistories.add(new MedicalRecord(patientId, historyText));
        }
    }
}
