    { "id": 2, "name": "Bob", "email": "bob@example.com", "score": 92 },
    { "id": 3, "name": "Charlie", "email": "charlie@example.com", "score": 78 }
  ]
}
```

Run the server:

```bash
json-server --watch db.json --port 3001
```

This will serve API endpoints like `GET /records`.

---

## 2. Frontend Implementation

### App.vue

Create a simple interface with Semantic UI components, Vue, and Canvas for visualization.

```vue
<template>
  <div class="ui container" style="margin-top: 2em;">
    <h2 class="ui header">Data Quality Analysis Tool</h2>

    <!-- Data Table -->
    <semantic-ui-table>
      <template #header>
        <tr>
          <th>ID</th>
          <th>Name</th>
          <th>Email</th>
          <th>Score</th>
        </tr>
      </template>
      <template #body>
        <tr v-for="record in records" :key="record.id">
          <td>{{ record.id }}</td>
          <td>{{ record.name }}</td>
          <td>{{ record.email }}</td>
          <td>{{ record.score }}</td>
        </tr>
      </template>
    </semantic-ui-table>

    <!-- Buttons -->
    <div style="margin-top: 1em;">
      <button class="ui primary button" @click="fetchData">Fetch Data</button>
      <button class="ui button" @click="analyzeData">Analyze Data</button>
    </div>

    <!-- Canvas for visualization -->
    <div style="margin-top: 2em;">
      <canvas id="dataChart" width="600" height="400"></canvas>
    </div>
  </div>
</template>

<script>
import { ref, onMounted } from 'vue'
import axios from 'axios'

export default {
  setup() {
    const records = ref([])

    const fetchData = async () => {
      try {
        const response = await axios.get('http://localhost:3001/records')
        records.value = response.data
      } catch (error) {
        console.error('Error fetching data:', error)
      }
    }

    const analyzeData = () => {
      // Example: visualize scores distribution
      const ctx = document.getElementById('dataChart').getContext('2d')

      // Prepare data
      const scores = records.value.map(r => r.score)

      // Count frequency of scores
      const frequency = {}
      scores.forEach(score => {
        const key = Math.floor(score / 10) * 10 // bucket by tens
        frequency[key] = (frequency[key] || 0) + 1
      })

      const labels = Object.keys(frequency).sort((a, b) => a - b)
      const data = labels.map(label => frequency[label])

      // Use Chart.js for visualization
      // Make sure to install Chart.js: npm install chart.js
      import { Chart } from 'chart.js'

      // Destroy previous chart if exists
      if (window.myChart) {
        window.myChart.destroy()
      }

      window.myChart = new Chart(ctx, {
        type: 'bar',
        data: {
          labels: labels.map(l => `${l}-${parseInt(l)+9}`),
          datasets: [{
            label: 'Score Distribution',
            data: data,
            backgroundColor: 'rgba(54, 162, 235, 0.6)',
            borderColor: 'rgba(54, 162, 235, 1)',
            borderWidth: 1
          }]
        },
        options: {
          responsive: false,
          scales: {
            y: {
              beginAtZero: true
            }
          }
        }
      })
    }

    onMounted(() => {
      fetchData()
    })

    return {
      records,
      fetchData,
      analyzeData
    }
  }
}
</script>
```

