```proto
syntax = "proto3";

package moviestreaming;

// Import Google's well-known types for timestamps
import "google/protobuf/timestamp.proto";

// Enum for movie genres
enum Genre {
  GENRE_UNSPECIFIED = 0;
  ACTION = 1;
  COMEDY = 2;
  DRAMA = 3;
  HORROR = 4;
  SCI_FI = 5;
  ROMANCE = 6;
  DOCUMENTARY = 7;
  THRILLER = 8;
}

// Movie message
message Movie {
  string id = 1; // Unique identifier
  string title = 2;
  string description = 3;
  Genre genre = 4;
  string director = 5;
  repeated string cast = 6;
  google.protobuf.Timestamp release_date = 7;
  string language = 8;
  string poster_url = 9;
  double rating = 10; // Average rating
  int32 duration_minutes = 11; // Duration in minutes
  bool is_available = 12; // Availability status
}

// Request and Response for listing movies
message ListMoviesRequest {
  string genre_filter = 1; // Optional genre filter
  string search_query = 2; // Optional search query
  int32 page_number = 3; // Pagination
  int32 page_size = 4;
}

message ListMoviesResponse {
  repeated Movie movies = 1;
  int32 total_results = 2;
  int32 total_pages = 3;
}

// Request and Response for getting movie details
message GetMovieRequest {
  string movie_id = 1;
}

message GetMovieResponse {
  Movie movie = 1;
}

// User account management
message User {
  string id = 1;
  string username = 2;
  string email = 3;
  string full_name = 4;
  google.protobuf.Timestamp date_joined = 5;
  bool is_active = 6;
}

// Request and Response for user registration
message RegisterUserRequest {
  string username = 1;
  string email = 2;
  string password = 3;
  string full_name = 4;
}

message RegisterUserResponse {
  User user = 1;
}

// Authentication (Login)
message LoginRequest {
  string email = 1;
  string password = 2;
}

message LoginResponse {
  string token = 1; // JWT or session token
  User user = 2;
}

// Subscription plans
enum SubscriptionPlan {
  PLAN_UNSPECIFIED = 0;
  BASIC = 1;
  STANDARD = 2;
  PREMIUM = 3;
}

// User subscriptions
message Subscription {
  string id = 1;
  string user_id = 2;
  SubscriptionPlan plan = 3;
  google.protobuf.Timestamp start_date = 4;
  google.protobuf.Timestamp end_date = 5;
  bool is_active = 6;
}

// Request and Response for subscribing
message SubscribeRequest {
  string user_id = 1;
  SubscriptionPlan plan = 2;
}

message SubscribeResponse {
  Subscription subscription = 1;
}

// Streaming session for watching movies
message StreamingSession {
  string session_id = 1;
  string user_id = 2;
  string movie_id = 3;
  google.protobuf.Timestamp start_time = 4;
  google.protobuf.Timestamp end_time = 5;
  string stream_url = 6; // URL or token for streaming
}

// Service definitions
service MovieService {
  rpc ListMovies (ListMoviesRequest) returns (ListMoviesResponse);
  rpc GetMovie (GetMovieRequest) returns (GetMovieResponse);
}

service UserService {
  rpc RegisterUser (RegisterUserRequest) returns (RegisterUserResponse);
  rpc Login (LoginRequest) returns (LoginResponse);
  rpc GetUserProfile (GetUserProfileRequest) returns (User);
}

message GetUserProfileRequest {
  string user_id = 1;
}

service SubscriptionService {
  rpc Subscribe (SubscribeRequest) returns (SubscribeResponse);
  rpc GetSubscription (GetSubscriptionRequest) returns (Subscription);
}

message GetSubscriptionRequest {
  string user_id = 1;
}

service StreamingService {
  rpc StartStreaming (StartStreamingRequest) returns (StreamingSession);
  rpc EndStreaming (EndStreamingRequest) returns (StreamingSession);
}

message StartStreamingRequest {
  string user_id = 1;
  string movie_id = 2;
}

message EndStreamingRequest {
  string session_id = 1;
}
```

### Explanation:
- **Movie Management:** Listing movies, retrieving details.
- **User Management:** Registration, login, profile retrieval.
- **Subscriptions:** Users can subscribe to different plans.
- **Streaming:** Initiate and end streaming sessions, with session info and stream URLs.

