Creating an After Effects plugin with a custom UI panel that integrates with the ElevenLabs API involves several steps, including setting up the plugin environment, designing the UI, handling API requests, and managing media assets within After Effects. Below is a comprehensive guide and example code snippets to help you build this plugin.

---

## Overview

**Features:**
- Login with ElevenLabs API credentials
- Select voice from available voices
- Input text, trigger speech synthesis on Enter
- Download generated MP3 and add as a new composition
- "3x" option to generate three versions simultaneously:
  - One main composition
  - Two alternative compositions

---

## Prerequisites

- Adobe After Effects CC with the CEP (Common Extensibility Platform) SDK
- Node.js environment for backend API calls (or use ExtendScript with `XMLHttpRequest`)
- Basic knowledge of JSX (ExtendScript) and HTML/JavaScript for CEP panels

---

## Step 1: Set Up the CEP Panel

Create a folder structure:

```
MyElevenLabsPanel/
├── index.html
├── main.js
├── panel.html
├── manifest.xml
```

### `manifest.xml`

Defines the extension:

```xml
<?xml version="1.0" encoding="UTF-8"?>
<ExtensionManifest Version="7.0" ExtensionBundleId="com.yourdomain.elevenlabs" ExtensionBundleVersion="1.0" xmlns="http://www.adobe.com/extension/manifest/7.0">
  <ExtensionList>
    <Extension Id="com.yourdomain.elevenlabs.panel"/>
  </ExtensionList>
  <ExecutionEnvironment>
    <HostList>
      <Host Name="AEFT" Version="23.0"/>
    </HostList>
    <LocaleList>
      <Locale Code="All"/>
    </LocaleList>
    <RequiredRuntimeList>
      <RequiredRuntime Name="CSXS" Version="11.0"/>
    </RequiredRuntimeList>
  </ExecutionEnvironment>
  <Extension Id="com.yourdomain.elevenlabs.panel" Version="1.0" xmlns="http://www.adobe.com/extension/manifest/7.0">
    <DispatchInfo>
      <Resources>
        <MainPath>panel.html</MainPath>
        <ScriptPath>main.js</ScriptPath>
      </Resources>
    </DispatchInfo>
  </Extension>
</ExtensionManifest>
```

---

## Step 2: Create the Panel UI (`panel.html`)

```html
<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8" />
  <title>ElevenLabs TTS Panel</title>
  <style>
    body { font-family: Arial, sans-serif; margin: 10px; }
    label { display: block; margin-top: 10px; }
    select, input[type=text] { width: 100%; padding: 5px; }
    button { margin-top: 10px; padding: 5px 10px; }
    #generate3x { margin-top: 10px; }
  </style>
</head>
<body>
  <h2>ElevenLabs TTS</h2>
  <label for="apiKey">API Key:</label>
  <input type="text" id="apiKey" placeholder="Enter your ElevenLabs API key" />

  <label for="voiceSelect">Select Voice:</label>
  <select id="voiceSelect">
    <option value="">Loading voices...</option>
  </select>

  <label for="textInput">Text:</label>
  <input type="text" id="textInput" placeholder="Type text and press Enter" />

  <button id="generateBtn">Generate</button>
  <button id="generate3x">3x</button>

  <script src="main.js"></script>
</body>
</html>
```

---

## Step 3: Handle UI Logic (`main.js`)

```js
(function() {
  const csInterface = new CSInterface();

  const apiKeyInput = document.getElementById('apiKey');
  const voiceSelect = document.getElementById('voiceSelect');
  const textInput = document.getElementById('textInput');
  const generateBtn = document.getElementById('generateBtn');
  const generate3xBtn = document.getElementById('generate3x');

  let voices = [];

  // Load voices when API key is entered
  document.getElementById('apiKey').addEventListener('change', () => {
    loadVoices();
  });

  // Load voices from API
  function loadVoices() {
    const apiKey = apiKeyInput.value.trim();
    if (!apiKey) {
      alert('Please enter your API key.');
      return;
    }

    fetchVoices(apiKey);
  }

  async function fetchVoices(apiKey) {
    try {
      const response = await fetch('https://api.elevenlabs.io/v1/voices', {
        headers: { 'xi-api-key': apiKey }
      });
      if (!response.ok) throw new Error('Failed to fetch voices');
      voices = await response.json();

      populateVoiceSelect();
    } catch (err) {
      alert('Error fetching voices: ' + err.message);
    }
  }

  function populateVoiceSelect() {
    voiceSelect.innerHTML = '';
    voices.forEach(voice => {
      const option = document.createElement('option');
      option.value = voice.voice_id;
      option.textContent = voice.name;
      voiceSelect.appendChild(option);
    });
  }

  // Trigger speech synthesis
  function synthesizeSpeech(times=1) {
    const apiKey = apiKeyInput.value.trim();
    const voiceId = voiceSelect.value;
    const text = textInput.value.trim();

    if (!apiKey || !voiceId || !text) {
      alert('Please enter API key, select a voice, and input text.');
      return;
    }

    if (times === 1) {
      generateSpeech(apiKey, voiceId, text);
    } else if (times === 3) {
      // Generate three versions
      generateSpeech(apiKey, voiceId, text, 'main');
      generateSpeech(apiKey, voiceId, text, 'alt1');
      generateSpeech(apiKey, voiceId, text, 'alt2');
    }
  }

  // Generate speech and add to AE
  async function generateSpeech(apiKey, voiceId, text, label='') {
    try {
      // Call ElevenLabs API
      const response = await fetch(`https://api.elevenlabs.io/v1/text-to-speech/${voiceId}`, {
        method: 'POST',
        headers: {
          'xi-api-key': apiKey,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({ text: text, voice_settings: {} })
      });
      if (!response.ok) throw new Error('API request failed');

      const arrayBuffer = await response.arrayBuffer();
      const blob = new Blob([arrayBuffer], { type: 'audio/mpeg' });
      const url = URL.createObjectURL(blob);

      // Save MP3 locally (using a temporary filename)
      // Since CEP panels can't directly save files, use the FileSaver API or prompt user
      // For simplicity, we'll send the blob to ExtendScript to save and import

      // Read blob as base64
      const reader = new FileReader();
      reader.onload = function() {
        const base64Data = reader.result.split(',')[1];
        // Send to ExtendScript
        csInterface.evalScript(`addAudioToAE("${base64Data}", "${label}")`);
      };
      reader.readAsDataURL(blob);
    } catch (err) {
      alert('Error generating speech: ' + err.message);
    }
  }

  // Event listeners
  textInput.addEventListener('keydown', (e) => {
    if (e.key === 'Enter') {
      synthesizeSpeech(1);
    }
  });

