async fn main() -> anyhow::Result<()> {
    // As a master over TCP
    let mut master_service = ModbusService::new(ConnectionType::Tcp("127.0.0.1:502".to_string()), Mode::Master).await;
    master_service.start().await?;

    // Read registers
    let regs = master_service.read_holding_registers(0, 10).await?;
    println!("Registers: {:?}", regs);

