### How it works:
- The window displays a dropdown of available Sorting Layers.
- When you click the "Apply to Selected" button, it iterates through all selected GameObjects.
- For each GameObject, it finds all components that have a `sortingLayerName` property and sets it to the selected Sorting Layer.

### Script:

```csharp
using UnityEngine;
using UnityEditor;
using System;
using System.Reflection;

public class SetSortingLayer : EditorWindow
{
    private string[] sortingLayerNames;
    private int selectedLayerIndex = 0;

    [MenuItem("Tools/Set Sorting Layer")]
    public static void ShowWindow()
    {
        GetWindow<SetSortingLayer>("Set Sorting Layer");
    }

    private void OnEnable()
    {
        // Fetch all sorting layer names
        sortingLayerNames = GetSortingLayerNames();

        // Optionally, set default selection
        selectedLayerIndex = 0;
    }

    private void OnGUI()
    {
        GUILayout.Label("Select Sorting Layer", EditorStyles.boldLabel);

        if (sortingLayerNames == null || sortingLayerNames.Length == 0)
        {
            EditorGUILayout.HelpBox("No Sorting Layers found.", MessageType.Warning);
            return;
        }

        selectedLayerIndex = EditorGUILayout.Popup("Sorting Layer", selectedLayerIndex, sortingLayerNames);

        if (GUILayout.Button("Apply to Selected"))
        {
            ApplySortingLayerToSelected();
        }
    }

    private string[] GetSortingLayerNames()
    {
        // Use SerializedObject to get sorting layers
        SerializedObject tagManager = new SerializedObject(AssetDatabase.LoadAllAssetsAtPath("ProjectSettings/TagManager.asset")[0]);
        SerializedProperty sortingLayersProp = tagManager.FindProperty("m_SortingLayers");

        string[] layerNames = new string[sortingLayersProp.arraySize];

        for (int i = 0; i < sortingLayersProp.arraySize; i++)
        {
            SerializedProperty layer = sortingLayersProp.GetArrayElementAtIndex(i);
            layerNames[i] = layer.FindPropertyRelative("name").stringValue;
        }

        return layerNames;
    }

    private void ApplySortingLayerToSelected()
    {
        if (Selection.gameObjects.Length == 0)
        {
            Debug.LogWarning("No GameObjects selected.");
            return;
        }

        string targetLayer = sortingLayerNames[selectedLayerIndex];

        int count = 0;

        foreach (GameObject go in Selection.gameObjects)
        {
            bool modified = false;

            // Get all components that might have a sortingLayerName property
            Component[] components = go.GetComponentsInChildren<Component>(true);

            foreach (Component comp in components)
            {
                if (comp == null) continue; // Skip missing scripts

                Type type = comp.GetType();

                // Find property named 'sortingLayerName' (case-insensitive)
                PropertyInfo prop = type.GetProperty("sortingLayerName", BindingFlags.Public | BindingFlags.Instance | BindingFlags.IgnoreCase);

                if (prop != null && prop.CanWrite && prop.PropertyType == typeof(string))
                {
                    try
                    {
                        prop.SetValue(comp, targetLayer, null);
                        modified = true;
                    }
                    catch (Exception e)
                    {
                        Debug.LogWarning($"Failed to set sortingLayerName on {comp.GetType().Name} of {go.name}: {e.Message}");
                    }
                }
                else
                {
                    // Alternatively, check for fields if property not found
                    FieldInfo field = type.GetField("sortingLayerName", BindingFlags.Public | BindingFlags.Instance | BindingFlags.IgnoreCase);
                    if (field != null && field.FieldType == typeof(string))
                    {
                        try
                        {
                            field.SetValue(comp, targetLayer);
                            modified = true;
                        }
                        catch (Exception e)
                        {
                            Debug.LogWarning($"Failed to set sortingLayerName field on {comp.GetType().Name} of {go.name}: {e.Message}");
                        }
                    }
                }
            }

            if (modified)
            {
                EditorUtility.SetDirty(go);
                count++;
            }
        }

        Debug.Log($"Applied Sorting Layer '{targetLayer}' to {count} GameObjects.");
    }
}
```

